// ============================================================================
// /insights — APG website snapshot + analytics dashboard
// ============================================================================
//
// Tracks every WP page change. On cron tick (every 15 min), checks each tracked
// page's WP `modified` timestamp. If it changed since last poll → captures the
// current screenshot from thum.io and stores the PNG bytes in KV under a
// timestamped key. The dashboard renders the latest snapshot + a timeline of
// historical versions, and deep-links into Microsoft Clarity heatmaps +
// session recordings so we can see WHERE users actually stop scrolling, click,
// or drop off on each version.

// WP page IDs we monitor. Add new ones here — auto-picked-up on next cron.
// Note: some pages were delete+recreate'd to clear Elementor postmeta + LiteSpeed
// cache (2026-05-25), so IDs may not be sequential.
const INSIGHTS_TRACKED_PAGES: Array<{ id: number; label: string }> = [
  { id: 1213, label: "Homepage" },
  { id: 1355, label: "About Us" },
  { id: 1356, label: "Services" },
  { id: 1362, label: "Construction Services" },
  { id: 1358, label: "Invest With Us" },
  { id: 1357, label: "Contact Us" },
  { id: 1359, label: "Career" },
  { id: 1361, label: "Blog" },
  { id: 1201, label: "Thank You" },
  { id: 1191, label: "City — Newark" },
  { id: 1192, label: "City — Trenton" },
  { id: 1198, label: "City — Philadelphia" },
  { id: 1246, label: "County — Mercer" },
  { id: 1242, label: "County — Essex" },
  { id: 1244, label: "County — Hudson" },
  { id: 1257, label: "County — Philadelphia" },
];

const CLARITY_PROJECT_ID = "wwbe84z9my";
const WP_REST_BASE = "https://atompropertygroup.com/wp-json/wp/v2";

// KV-cached WP page meta. Mido reported /insights loading slowly on
// 2026-05-27 — root cause was N parallel WP.com REST calls per page render.
// Now we cache for 10 minutes (the cron at */15 refreshes when it polls
// for changes). Pass `forceRefresh=true` from the cron path.
async function fetchWpPageMeta(env: Env, pageId: number, forceRefresh = false): Promise<{
  id: number; modified: string; link: string; title: string; slug: string;
} | null> {
  if (!env.WP_AUTH_HEADER) {
    console.warn("[insights] WP_AUTH_HEADER not configured");
    return null;
  }
  const cacheKey = `insights:meta:${pageId}`;
  if (!forceRefresh) {
    try {
      const cached = await env.DIAL_STATE.get(cacheKey);
      if (cached) return JSON.parse(cached);
    } catch {}
  }
  const res = await fetch(
    `${WP_REST_BASE}/pages/${pageId}?_fields=id,modified,link,title,slug`,
    { headers: { Authorization: env.WP_AUTH_HEADER } }
  );
  if (!res.ok) {
    // On WP miss, return last cached value (better stale than blank) if any.
    try {
      const cached = await env.DIAL_STATE.get(cacheKey);
      if (cached) return JSON.parse(cached);
    } catch {}
    return null;
  }
  const p: any = await res.json();
  const meta = {
    id: p.id,
    modified: p.modified,
    link: p.link,
    title: p.title?.rendered || "",
    slug: p.slug || "",
  };
  // 6-hour TTL — WP modified rarely changes that often. Bumped from 10min
  // 2026-05-28 to cut KV write volume by ~36x. Insights cron polls every
  // hour anyway via tick rotation. Catch put errors so KV quota issues
  // don't surface as "Unable to fetch WP metadata" cards in the dashboard.
  try {
    await env.DIAL_STATE.put(cacheKey, JSON.stringify(meta), { expirationTtl: 60 * 60 * 6 });
  } catch (e) {
    console.warn(`[insights] WP meta cache write failed (kv quota?): ${e}`);
  }
  return meta;
}

async function captureAndStoreSnapshot(
  env: Env,
  pageId: number,
  pageUrl: string,
  modifiedAt: string,
  width: number = 1440,
): Promise<{ key: string; bytes: number } | null> {
  const thumUrl =
    "https://image.thum.io/get/width/" + width +
    "/crop/2400/png/" + pageUrl;
  const imgRes = await fetch(thumUrl);
  if (!imgRes.ok) {
    console.warn(`[insights] thum.io failed ${imgRes.status} for ${pageUrl}`);
    return null;
  }
  const buf = await imgRes.arrayBuffer();
  const bytes = buf.byteLength;
  const captureIso = new Date().toISOString();
  const key = `insights:snap:${pageId}:${captureIso}`;
  await env.DIAL_STATE.put(key, buf, {
    expirationTtl: 60 * 60 * 24 * 90,
    metadata: { pageId, pageUrl, modifiedAt, capturedAt: captureIso, width, bytes },
  });
  const timelineKey = `insights:timeline:${pageId}`;
  const timelineRaw = await env.DIAL_STATE.get(timelineKey);
  const timeline: any[] = timelineRaw ? JSON.parse(timelineRaw) : [];
  timeline.unshift({ key, capturedAt: captureIso, modifiedAt, pageUrl, width, bytes });
  await env.DIAL_STATE.put(
    timelineKey,
    JSON.stringify(timeline.slice(0, 50)),
    { expirationTtl: 60 * 60 * 24 * 180 }
  );
  return { key, bytes };
}

// Daily end-of-day baseline — captures EVERY tracked page once per day,
// regardless of whether WP modified timestamp changed. This guarantees a
// permanent daily snapshot record even on pages that don't get edited often,
// so when we look at the timeline weeks later we have continuous coverage.
// Dedupe: if today's daily key was already set, skip (prevents double-runs
// if cron fires twice due to CF retry).
async function dailyInsightsBaseline(env: Env): Promise<void> {
  const today = new Date().toISOString().slice(0, 10);  // YYYY-MM-DD UTC
  const sentinelKey = `insights:daily_done:${today}`;
  const already = await env.DIAL_STATE.get(sentinelKey);
  if (already) {
    console.log(`[daily-baseline] already ran today (${today}) — skipping`);
    return;
  }
  console.log(`[daily-baseline] starting for ${today} — ${INSIGHTS_TRACKED_PAGES.length} pages`);
  let captured = 0;
  let failed = 0;
  for (const { id, label } of INSIGHTS_TRACKED_PAGES) {
    try {
      const meta = await fetchWpPageMeta(env, id);
      if (!meta) {
        console.warn(`[daily-baseline] WP meta fetch failed for ${label} (id=${id})`);
        failed++;
        continue;
      }
      const result = await captureAndStoreSnapshot(env, id, meta.link, meta.modified);
      if (result) {
        captured++;
        console.log(`[daily-baseline] captured ${label}: ${result.bytes} bytes`);
      } else {
        failed++;
      }
      // Also bump last-known modified so the change-poll doesn't immediately
      // re-capture on its next tick
      await env.DIAL_STATE.put(`insights:lastmod:${id}`, meta.modified, {
        expirationTtl: 60 * 60 * 24 * 180,
      });
    } catch (e: any) {
      console.warn(`[daily-baseline] failed ${label}: ${e?.message || e}`);
      failed++;
    }
  }
  // Sentinel TTL = 25h (longer than 24 so we don't accidentally re-fire if cron is slow)
  await env.DIAL_STATE.put(sentinelKey, new Date().toISOString(), {
    expirationTtl: 60 * 60 * 25,
  });
  console.log(`[daily-baseline] done: ${captured} captured, ${failed} failed`);
}

async function pollInsightsForChanges(env: Env): Promise<void> {
  for (const { id, label } of INSIGHTS_TRACKED_PAGES) {
    try {
      // Force a fresh WP fetch in the cron path so the cache is always
      // populated with the latest modified timestamp.
      const meta = await fetchWpPageMeta(env, id, true);
      if (!meta) continue;
      const lastModKey = `insights:lastmod:${id}`;
      const lastMod = await env.DIAL_STATE.get(lastModKey);
      if (lastMod === meta.modified) continue;
      console.log(`[insights] change detected: ${label} (id=${id}) was=${lastMod || "(never)"} now=${meta.modified}`);
      const result = await captureAndStoreSnapshot(env, id, meta.link, meta.modified);
      if (result) {
        await env.DIAL_STATE.put(lastModKey, meta.modified, {
          expirationTtl: 60 * 60 * 24 * 180,
        });
        console.log(`[insights] captured ${label}: ${result.bytes} bytes`);
      }
    } catch (e) {
      console.warn(`[insights] failed for ${label}: ${e}`);
    }
  }
}

async function handleInsightsListPages(env: Env): Promise<Response> {
  // Parallel fetch: was sequential which timed out at ~16 pages × 500ms each.
  // Each page is independent — fan out, fan in. Total wall time ≈ slowest
  // single call instead of sum of all calls.
  const settled = await Promise.allSettled(
    INSIGHTS_TRACKED_PAGES.map(async ({ id, label }) => {
      const [meta, timelineRaw] = await Promise.all([
        fetchWpPageMeta(env, id),
        env.DIAL_STATE.get(`insights:timeline:${id}`),
      ]);
      if (!meta) return { id, label, error: "wp_fetch_failed" };
      const timeline = timelineRaw ? JSON.parse(timelineRaw) : [];
      const latest = timeline[0] || null;
      const claritySlug = encodeURIComponent(meta.link);
      return {
        id, label,
        title: meta.title,
        slug: meta.slug,
        link: meta.link,
        modified: meta.modified,
        snapshotCount: timeline.length,
        latestKey: latest?.key,
        latestCapturedAt: latest?.capturedAt,
        clarityHeatmapUrl: `https://clarity.microsoft.com/projects/view/${CLARITY_PROJECT_ID}/heatmaps?date=Last+7+days&Page=${claritySlug}`,
        clarityRecordingsUrl: `https://clarity.microsoft.com/projects/view/${CLARITY_PROJECT_ID}/recordings?date=Last+7+days&Page=${claritySlug}`,
      };
    })
  );

  const result = settled.map((s, i) => {
    const tracked = INSIGHTS_TRACKED_PAGES[i];
    return s.status === "fulfilled"
      ? s.value
      : { id: tracked.id, label: tracked.label, error: String((s as any).reason?.message || (s as any).reason) };
  });

  return new Response(JSON.stringify({ pages: result }, null, 2), {
    status: 200,
    headers: { "content-type": "application/json", "cache-control": "no-store" },
  });
}

async function handleInsightsSnapshots(env: Env, pageId: string): Promise<Response> {
  const timelineRaw = await env.DIAL_STATE.get(`insights:timeline:${pageId}`);
  const timeline = timelineRaw ? JSON.parse(timelineRaw) : [];
  return new Response(JSON.stringify({ pageId: Number(pageId), timeline }, null, 2), {
    status: 200,
    headers: { "content-type": "application/json", "cache-control": "no-store" },
  });
}

async function handleInsightsCapture(req: Request, env: Env): Promise<Response> {
  let body: any = {};
  try { body = await req.json(); } catch {}
  const pageId = Number(body.pageId);
  if (!pageId || !INSIGHTS_TRACKED_PAGES.find(p => p.id === pageId)) {
    return new Response(JSON.stringify({ error: "invalid pageId" }), {
      status: 400, headers: { "content-type": "application/json" },
    });
  }
  const meta = await fetchWpPageMeta(env, pageId);
  if (!meta) {
    return new Response(JSON.stringify({ error: "wp_fetch_failed" }), {
      status: 502, headers: { "content-type": "application/json" },
    });
  }
  const result = await captureAndStoreSnapshot(env, pageId, meta.link, meta.modified);
  if (!result) {
    return new Response(JSON.stringify({ error: "capture_failed" }), {
      status: 502, headers: { "content-type": "application/json" },
    });
  }
  await env.DIAL_STATE.put(`insights:lastmod:${pageId}`, meta.modified, {
    expirationTtl: 60 * 60 * 24 * 180,
  });
  return new Response(JSON.stringify({ ok: true, key: result.key, bytes: result.bytes }), {
    status: 200, headers: { "content-type": "application/json" },
  });
}

async function handleInsightsSnap(env: Env, key: string): Promise<Response> {
  // Critical: url.pathname keeps colons URL-encoded (%3A), so the key arrives
  // looking like "insights%3Asnap%3A1213%3A..." even though the stored KV key
  // uses literal colons. Decode before lookup.
  let decoded: string;
  try { decoded = decodeURIComponent(key); } catch { decoded = key; }
  const fullKey = decoded.startsWith("insights:snap:") ? decoded : `insights:snap:${decoded}`;
  const bytes = await env.DIAL_STATE.get(fullKey, "arrayBuffer");
  if (!bytes) {
    return new Response("Not Found", { status: 404 });
  }
  return new Response(bytes, {
    status: 200,
    headers: {
      "content-type": "image/png",
      "cache-control": "public, max-age=86400",
    },
  });
}

const INSIGHTS_DASHBOARD_HTML = INSIGHTS_DASHBOARD_HTML_RAW;

// ============================================================================
// Auto-blog — generate + publish a value-driven post every BLOG_CADENCE_DAYS
// ============================================================================

// Cron tick: if it's been long enough since the last post, generate a new one.
// Runs every 15 min (piggy-backs on existing cron); the cadence check inside
// means we only actually generate once per BLOG_CADENCE_DAYS days.
async function autoBlogTick(env: Env): Promise<void> {
  // Audit 1.5 follow-up — KV instrumentation so we can see exactly why the
  // auto-blog cron has never produced a post. Every tick writes a status
  // record (under `autoblog:last_tick`) regardless of outcome.
  const tickStatus: Record<string, any> = {
    at: new Date().toISOString(),
    ready: false,
    attempted: false,
    ok: false,
    error: null,
    post_id: null,
    title: null,
  };
  try {
    const ready = await isReadyToPost(env);
    tickStatus.ready = ready;
    if (!ready) {
      return;  // not enough time has passed since last post — skip KV write to spare daily quota
    }
    tickStatus.attempted = true;
    console.log(`[cron-blog] cadence check passed — generating new post`);
    const result = await generateAndPublishBlogPost(env);
    if (result.ok) {
      await recordLastPosted(env);
      tickStatus.ok = true;
      tickStatus.post_id = result.postId;
      tickStatus.title = result.title;
      console.log(`[cron-blog] published draft "${result.title}" → post_id=${result.postId}`);
    } else {
      tickStatus.error = result.error;
      console.warn(`[cron-blog] failed: ${result.error}`);
    }
  } catch (e: any) {
    tickStatus.error = `threw: ${e?.message || String(e)}`;
    console.error(`[cron-blog] threw: ${e?.message || e}`);
  } finally {
    // Only write KV when we actually attempted — skip the "not ready" ticks
    // so we don't burn the 1000/day KV write quota on cadence-not-met no-ops.
    if (tickStatus.attempted) {
      try {
        await env.DIAL_STATE.put("autoblog:last_tick", JSON.stringify(tickStatus), {
          expirationTtl: 60 * 60 * 24 * 14,
        });
        const ringKey = "autoblog:ticks:recent";
        const prev = await env.DIAL_STATE.get(ringKey);
        const arr = prev ? JSON.parse(prev) : [];
        arr.unshift(tickStatus);
        while (arr.length > 10) arr.pop();
        await env.DIAL_STATE.put(ringKey, JSON.stringify(arr), {
          expirationTtl: 60 * 60 * 24 * 30,
        });
      } catch {}
    }
  }
}

// Manual trigger from /admin/blog/generate. Accepts body {force?: boolean,
// topicSlug?: string} for testing — force bypasses the cadence check, topicSlug
// picks a specific topic instead of the next-unused one.
async function handleAdminBlogGenerate(req: Request, env: Env): Promise<Response> {
  let body: any = {};
  try { body = await req.json(); } catch {}
  const force = body.force === true;
  if (!force && !(await isReadyToPost(env))) {
    return new Response(JSON.stringify({
      error: "cadence_not_met",
      hint: "Pass {force: true} to bypass the 3-day cadence check.",
    }), { status: 409, headers: { "content-type": "application/json" } });
  }

  const result = await generateAndPublishBlogPost(env, body.topicSlug);
  if (result.ok) {
    await recordLastPosted(env);
    return new Response(JSON.stringify({
      ok: true, postId: result.postId, title: result.title,
      status: result.status, link: result.link,
    }, null, 2), { status: 200, headers: { "content-type": "application/json" } });
  }
  return new Response(JSON.stringify({ ok: false, error: result.error }), {
    status: 502, headers: { "content-type": "application/json" },
  });
}

// Core generation + publish flow.
async function generateAndPublishBlogPost(
  env: Env,
  forceTopicSlug?: string,
): Promise<
  | { ok: true; postId: number; title: string; status: string; link: string }
  | { ok: false; error: string }
> {
  // 1. Pick topic
  let topic: BlogTopic | null;
  if (forceTopicSlug) {
    topic = BLOG_TOPIC_POOL.find((t) => t.slug === forceTopicSlug) || null;
    if (!topic) return { ok: false, error: `topic_not_found: ${forceTopicSlug}` };
  } else {
    topic = await pickNextTopic(env);
  }
  if (!topic) return { ok: false, error: "no_topic_available" };

  console.log(`[blog] generating: ${topic.slug}`);

  // 2. Call Claude to write the post
  if (!env.ANTHROPIC_API_KEY) {
    return { ok: false, error: "ANTHROPIC_API_KEY not configured" };
  }
  const prompt = buildBlogPrompt(topic);
  let claudeJson: any;
  try {
    const claudeRes = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 2500,
        messages: [{ role: "user", content: prompt }],
      }),
    });
    if (!claudeRes.ok) {
      const txt = await claudeRes.text();
      return { ok: false, error: `claude_${claudeRes.status}: ${txt.slice(0, 300)}` };
    }
    const claudeData: any = await claudeRes.json();
    const text = claudeData?.content?.[0]?.text || "";
    // Strip any markdown code fences
    const cleaned = text.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "").trim();
    try {
      claudeJson = JSON.parse(cleaned);
    } catch (e) {
      return { ok: false, error: `claude_invalid_json: ${cleaned.slice(0, 300)}` };
    }
  } catch (e: any) {
    return { ok: false, error: `claude_fetch_threw: ${e?.message || e}` };
  }

  if (!claudeJson.title || !claudeJson.body_html) {
    return { ok: false, error: "claude_missing_fields" };
  }

  // 3. Replace inline image placeholders with uploaded WP media URLs.
  //    Claude inserts `<p><!-- INLINE_IMAGE --></p>` at natural breaks; we split
  //    the body on those markers, upload one image per gap, and rejoin.
  let bodyHtml = claudeJson.body_html as string;
  const placeholderRe = /<p>\s*<!--\s*INLINE_IMAGE\s*-->\s*<\/p>/gi;
  const segments = bodyHtml.split(placeholderRe);
  const placeholderCount = segments.length - 1;  // N markers split into N+1 segments
  if (placeholderCount > 0) {
    const inlineCount = Math.min(placeholderCount, 2);  // cap at 2 images
    const inlineUrls = pickInlineImages(topic.slug, inlineCount);
    const imgTags: string[] = [];
    for (let i = 0; i < inlineCount; i++) {
      try {
        const mediaId = await uploadImageToWp(env, inlineUrls[i], `${topic.slug}-inline-${i + 1}`);
        const meta = await fetchWpMediaSourceUrl(env, mediaId);
        if (meta?.sourceUrl) {
          imgTags.push(`<figure style="margin:32px 0;"><img src="${meta.sourceUrl}" alt="${(claudeJson.title || topic.title).replace(/"/g, "&quot;")}" style="width:100%;height:auto;border-radius:8px;display:block;" loading="lazy"></figure>`);
        } else {
          imgTags.push("");  // empty replacement if media URL lookup failed
        }
      } catch (e: any) {
        console.warn(`[blog] inline image upload failed: ${e?.message || e}`);
        imgTags.push("");
      }
    }
    // Rejoin: segment[0] + img[0] + segment[1] + img[1] + ... + segment[N]
    // Any placeholders beyond inlineCount get a blank replacement.
    while (imgTags.length < placeholderCount) imgTags.push("");
    let rebuilt = segments[0];
    for (let i = 0; i < imgTags.length; i++) {
      rebuilt += imgTags[i] + (segments[i + 1] || "");
    }
    bodyHtml = rebuilt;
    console.log(`[blog] inline images: ${inlineCount} embedded (of ${placeholderCount} placeholders)`);
  }

  // 4. Append the standardized CTA box (defense-in-depth — even if Claude omits it)
  const fullBody = bodyHtml + BLOG_CTA_BOX;

  // 5. Pick image + upload to WP media library so it can be set as featured image
  const imageUrl = pickImageForTopic(topic.slug);
  let featuredMediaId: number | undefined;
  try {
    featuredMediaId = await uploadImageToWp(env, imageUrl, topic.slug);
  } catch (e: any) {
    console.warn(`[blog] image upload failed (continuing without featured image): ${e?.message || e}`);
  }

  // 5. POST to WP
  const postBody: any = {
    title: claudeJson.title,
    slug: topic.slug,
    status: BLOG_DEFAULT_STATUS,
    content: fullBody,
    excerpt: claudeJson.excerpt || "",
    author: BLOG_AUTHOR_USER_ID,
    categories: [],   // (could set up a real-estate-tips category later)
    tags: [],         // ditto
  };
  if (featuredMediaId) postBody.featured_media = featuredMediaId;

  const wpRes = await fetch(`${WP_REST_BASE}/posts`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      Authorization: env.WP_AUTH_HEADER,
    },
    body: JSON.stringify(postBody),
  });
  if (!wpRes.ok) {
    const txt = await wpRes.text();
    return { ok: false, error: `wp_post_${wpRes.status}: ${txt.slice(0, 300)}` };
  }
  const wpJson: any = await wpRes.json();
  await markTopicUsed(env, topic.slug);

  return {
    ok: true,
    postId: wpJson.id,
    title: wpJson.title?.rendered || claudeJson.title,
    status: wpJson.status,
    link: wpJson.link,
  };
}

// After uploading via uploadImageToWp(), fetch the canonical source_url so we
// embed the WP-hosted URL in the post body (not the original Unsplash URL).
async function fetchWpMediaSourceUrl(env: Env, mediaId: number): Promise<{ sourceUrl: string } | null> {
  if (!env.WP_AUTH_HEADER) return null;
  const res = await fetch(`${WP_REST_BASE}/media/${mediaId}?_fields=source_url`, {
    headers: { Authorization: env.WP_AUTH_HEADER },
  });
  if (!res.ok) return null;
  const j: any = await res.json();
  return j.source_url ? { sourceUrl: j.source_url } : null;
}

// Server-render the Insights dashboard HTML — fetches all WP metadata + KV
// timeline counts in parallel, then emits a static HTML page with the cards
// already rendered. No client-side fetch, no Loading state. Buttons + ATTOM
// lookup form remain JS-driven (those are POST actions).
async function renderInsightsDashboardServerSide(env: Env): Promise<string> {
  const buildTs = new Date().toISOString();

  // Fetch all page metadata + their timeline lengths in parallel
  const settled = await Promise.allSettled(
    INSIGHTS_TRACKED_PAGES.map(async ({ id, label }) => {
      const [meta, timelineRaw] = await Promise.all([
        fetchWpPageMeta(env, id),
        env.DIAL_STATE.get(`insights:timeline:${id}`),
      ]);
      const timeline = timelineRaw ? JSON.parse(timelineRaw) : [];
      const latest = timeline[0] || null;
      return { id, label, meta, latest, snapshotCount: timeline.length };
    })
  );

  const fmtDate = (iso: string | undefined) => {
    if (!iso) return "—";
    try {
      const d = new Date(iso);
      return d.toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
    } catch { return "?"; }
  };
  const esc = (s: any) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" } as any)[c]);

  // Render each card
  const cardsHtml = settled.map((s, i) => {
    const tracked = INSIGHTS_TRACKED_PAGES[i];
    if (s.status === "rejected" || !s.value.meta) {
      return `<div class="card" style="border:1px solid #f5c2c2;background:#fff5f5;">
        <div class="thumb" style="aspect-ratio:16/10;background:#fdecec;display:flex;align-items:center;justify-content:center;color:#8b1a1a;font-size:12px;text-align:center;padding:16px;">Unable to fetch WP metadata<br>(id ${tracked.id})</div>
        <div class="body" style="padding:14px 16px 16px;">
          <div style="font-family:'Playfair Display',serif;font-weight:700;font-size:14px;margin-bottom:6px;">${esc(tracked.label)}</div>
          <div style="font-size:11px;color:#8b1a1a;">${esc(s.status === "rejected" ? (s as any).reason?.message : "wp_fetch_failed")}</div>
        </div>
      </div>`;
    }
    const v = s.value;
    const meta = v.meta!;
    const latest = v.latest;
    const claritySlug = encodeURIComponent(meta.link);
    const thumb = latest?.key
      ? `<img src="/insights/snap/${encodeURIComponent(latest.key)}" alt="" style="width:100%;height:100%;object-fit:cover;object-position:top;display:block;">`
      : `<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#6B7280;font-style:italic;font-size:13px;padding:16px;text-align:center;">No snapshot yet — click "Snap now"</div>`;
    return `<div class="card" style="background:white;border:1px solid #E5E1D8;border-radius:12px;overflow:hidden;">
      <div class="thumb" style="background:#f5f1e8;aspect-ratio:16/10;position:relative;overflow:hidden;">${thumb}</div>
      <div class="body" style="padding:14px 16px 16px;">
        <div style="font-family:'Playfair Display',serif;font-weight:700;font-size:14px;margin-bottom:2px;">${esc(v.label)}</div>
        <div style="font-size:11px;color:#6B7280;margin-bottom:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${esc(meta.link)}</div>
        <div style="display:flex;justify-content:space-between;font-size:11px;color:#6B7280;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid #E5E1D8;">
          <span>WP modified: <strong style="color:#1A2840;">${fmtDate(meta.modified)}</strong></span>
          <span><strong style="color:#1A2840;">${v.snapshotCount}</strong> snap${v.snapshotCount === 1 ? "" : "s"}</span>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;">
          <button onclick="snapPage(${tracked.id}, this)" style="font-size:10px;padding:6px 10px;border-radius:4px;border:none;background:#1A2840;color:#FAFAF7;cursor:pointer;letter-spacing:0.05em;text-transform:uppercase;font-weight:700;font-family:inherit;">Snap now</button>
          <a href="https://clarity.microsoft.com/projects/view/${CLARITY_PROJECT_ID}/heatmaps?date=Last+7+days&Page=${claritySlug}" target="_blank" rel="noopener" style="font-size:10px;padding:6px 10px;border-radius:4px;background:linear-gradient(135deg,#BF7BFF,#7B5BFF);color:white;text-decoration:none;letter-spacing:0.05em;text-transform:uppercase;font-weight:700;">Heatmap &#8599;</a>
          <a href="https://clarity.microsoft.com/projects/view/${CLARITY_PROJECT_ID}/recordings?date=Last+7+days&Page=${claritySlug}" target="_blank" rel="noopener" style="font-size:10px;padding:6px 10px;border-radius:4px;background:linear-gradient(135deg,#BF7BFF,#7B5BFF);color:white;text-decoration:none;letter-spacing:0.05em;text-transform:uppercase;font-weight:700;">Sessions &#8599;</a>
          <a href="${esc(meta.link)}" target="_blank" rel="noopener" style="font-size:10px;padding:6px 10px;border-radius:4px;border:1px solid #E5E1D8;background:white;color:#1A2840;text-decoration:none;letter-spacing:0.05em;text-transform:uppercase;font-weight:700;">Visit &#8599;</a>
        </div>
      </div>
    </div>`;
  }).join("\n");

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Insights · APG</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,400;0,700;1,400;1,700&display=swap" rel="stylesheet">
<style>
  body { margin:0; font-family: 'Inter', -apple-system, sans-serif; background: #FAFAF7; color: #1A2840; }
  .wrap { max-width: 1400px; margin: 0 auto; padding: 28px; }
  h1 { font-family: 'Playfair Display', Georgia, serif; font-size: 38px; margin: 0 0 4px; }
  h1 em { color: #B58800; font-style: italic; }
  .sub { color: #6B7280; font-size: 14px; margin-bottom: 24px; }
  .pages { display: grid; grid-template-columns: repeat(auto-fill, minmax(380px, 1fr)); gap: 20px; }
  .toolbar { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 16px; padding: 14px; background: white; border: 1px solid #E5E1D8; border-radius: 8px; align-items: center; }
  .toolbar button { padding: 10px 18px; border: none; border-radius: 6px; cursor: pointer; font-size: 13px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; font-family: inherit; }
  .status { padding: 10px 14px; background: #1A2840; color: #FAFAF7; border-radius: 6px; font-size: 12px; margin-bottom: 16px; display: none; white-space: pre-wrap; }
  .status.show { display: block; }
  .status.ok { background: #0e6e2f; }
  .status.error { background: #8b1a1a; }
  .footer-tag { margin-top: 28px; font-size: 11px; color: #9CA3AF; text-align: center; }
</style>
</head>
<body>
<div class="wrap">
  <h1>Website <em>Insights</em></h1>
  <div class="sub">Server-rendered ${INSIGHTS_TRACKED_PAGES.length} tracked pages &middot; auto-snapshots on every WP page change &middot; Microsoft Clarity heatmaps + sessions</div>

  <div class="toolbar">
    <button onclick="generateBlog(this)" style="background:linear-gradient(135deg,#BF7BFF,#7B5BFF);color:white;">+ Generate Blog Post Now</button>
    <button onclick="snapAll(this)" style="background:#1A2840;color:#FAFAF7;">Snap All Pages</button>
  </div>

  <div class="status" id="status"></div>

  <div class="pages">
${cardsHtml}
  </div>

  <div class="footer-tag">build ${buildTs} · server-rendered · ${INSIGHTS_TRACKED_PAGES.length} pages</div>
</div>

<script>
  function setStatus(text, kind) {
    var el = document.getElementById('status');
    el.textContent = text || '';
    el.className = 'status' + (text ? ' show' : '') + (kind ? ' ' + kind : '');
    if (text && kind === 'ok') setTimeout(function(){ setStatus(''); }, 4000);
  }

  function snapPage(id, btn) {
    var orig = btn.innerHTML; btn.disabled = true; btn.innerHTML = 'Snapping...';
    fetch('/insights/api/capture', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ pageId: id }) })
      .then(function(r){ return r.json(); })
      .then(function(d){ btn.disabled = false; btn.innerHTML = orig; if (d.ok) { setStatus('✓ Captured (' + Math.round(d.bytes/1024) + ' KB) — reload page to see new thumbnail.', 'ok'); } else { setStatus('Capture failed: ' + (d.error || '?'), 'error'); } })
      .catch(function(e){ btn.disabled = false; btn.innerHTML = orig; setStatus('Capture error: ' + e.message, 'error'); });
  }

  function snapAll(btn) {
    if (!confirm('Capture every tracked page now? ~1-2 min.')) return;
    btn.disabled = true; var orig = btn.innerHTML; btn.innerHTML = 'Snapping...';
    var ids = ${JSON.stringify(INSIGHTS_TRACKED_PAGES.map((p) => p.id))};
    function next(i) {
      if (i >= ids.length) { btn.disabled = false; btn.innerHTML = orig; setStatus('✓ Snapped ' + ids.length + ' pages. Reload to see thumbnails.', 'ok'); return; }
      setStatus('Capturing ' + (i+1) + '/' + ids.length + '...');
      fetch('/insights/api/capture', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ pageId: ids[i] }) })
        .finally(function(){ next(i+1); });
    }
    next(0);
  }

  function generateBlog(btn) {
    if (!confirm('Generate a blog draft now? Calls Claude API.')) return;
    var orig = btn.innerHTML; btn.disabled = true; btn.innerHTML = 'Generating... ~30s';
    setStatus('Generating blog post... please wait ~30 seconds.');
    fetch('/admin/blog/generate', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ force: true }) })
      .then(function(r){ return r.json().then(function(d){ return { ok: r.ok, data: d }; }); })
      .then(function(res){ btn.disabled = false; btn.innerHTML = orig; if (res.data.ok) { setStatus('✓ Draft: ' + res.data.title + '\\n' + res.data.link, 'ok'); if (confirm('Open the draft in WP?')) { window.open('https://atompropertygroup.com/wp-admin/post.php?post=' + res.data.postId + '&action=edit', '_blank'); } } else { setStatus('Blog failed: ' + (res.data.error || '?'), 'error'); } })
      .catch(function(e){ btn.disabled = false; btn.innerHTML = orig; setStatus('Blog error: ' + e.message, 'error'); });
  }

  // Note: backfillAcq() and attomLookup() removed from /insights toolbar per
  // operator direction (2026-05-26). These belong on a CRM-management dashboard
  // (probably /deals) not website-Insights. The endpoints still exist server-
  // side; just no UI on this page.
</script>
</body>
</html>`;
}

// ---- /admin/csv/motivated-sellers — RJ's call list ----
//
// Pages through every opp in the ACQ pipeline, filters to contacts tagged
// motivated-seller (or any per-signal tag), joins their ATTOM enrichment from
// KV cache + GHL contact details, and emits a CSV download.
//
// Columns: opp_id, contact_name, phone, email, address, city, state, zip,
//   stage, motivated_flags, avm, mao, beds, baths, sqft, year_built,
//   last_sale_amt, last_sale_date, tax_assessed, owner_of_record,
//   owner_mailing_absentee, equity_amount, equity_multiple, ghl_contact_url
async function handleMotivatedSellersCsv(env: Env): Promise<Response> {
  const pit = env.BLAKE_GHL_PIT;
  const rows: string[][] = [];

  // CSV header
  const header = [
    "opp_id", "stage_id", "contact_name", "phone", "email",
    "address", "city", "state", "zip",
    "motivated_flags", "absentee", "high_equity", "recent_transfer",
    "avm_value", "avm_low", "avm_high", "avm_confidence",
    "mao_computed", "equity_amount", "equity_multiple",
    "beds", "baths", "sqft", "year_built", "lot_acres",
    "last_sale_amount", "last_sale_date", "tax_assessed",
    "owner_of_record", "owner_mailing",
    "ghl_contact_url",
  ];
  rows.push(header);

  // Paginate through every opp in ACQ
  let startAfter: any = undefined;
  let startAfterId: any = undefined;
  let safetyCounter = 0;
  while (safetyCounter++ < 100) {  // hard cap at 100 batches (= 5000 opps)
    const params = new URLSearchParams({
      location_id: APG_LOCATION_ID,
      pipeline_id: ACQ_PIPELINE_ID,
      limit: "50",
    });
    if (startAfter)   params.set("startAfter",   String(startAfter));
    if (startAfterId) params.set("startAfterId", String(startAfterId));

    const oppRes = await fetch(`${GHL_BASE}/opportunities/search?${params.toString()}`, {
      method: "GET", headers: ghlHeaders(pit),
    });
    if (!oppRes.ok) {
      console.warn(`[csv] ghl search failed ${oppRes.status}`);
      break;
    }
    const oppJson: any = await oppRes.json();
    const opps: any[] = oppJson?.opportunities ?? [];
    if (opps.length === 0) break;

    for (const opp of opps) {
      const contactId = opp?.contact?.id || opp?.contactId;
      if (!contactId) continue;

      // Check the embedded contact tags first to filter early
      const embeddedTags: string[] = opp?.contact?.tags ?? [];
      const hasMotivatedTag = embeddedTags.some((t) =>
        t === "motivated-seller" || t === "absentee-owner" ||
        t === "high-equity" || t === "recent-transfer-probate"
      );

      // For contacts without tags, also try the ATTOM cache as fallback —
      // they might be motivated but not yet tagged (if backfill hasn't run).
      // To keep the CSV focused, only include if tagged OR cached ATTOM shows
      // a signal. We need the full contact for the address.
      const contact = await getContactDetail(pit, contactId);
      if (!contact) continue;

      const addrParts = [contact.address1, contact.city, contact.state, contact.postalCode]
        .map((s: any) => String(s || "").trim()).filter(Boolean);
      const fullAddress = addrParts.join(", ");

      // Cheap KV cache check — if ATTOM enrichment was done before, get it
      let attom: any = null;
      let motivated: any = null;
      if (fullAddress && addrParts.length >= 2) {
        const cacheKey = "attom:enrich:" + fullAddress.toLowerCase().replace(/\s+/g, " ").trim();
        const cachedRaw = await env.DIAL_STATE.get(cacheKey);
        if (cachedRaw) {
          try { attom = JSON.parse(cachedRaw); } catch {}
        }
        if (attom && !attom.error) {
          motivated = scoreMotivatedSignals(attom);
        }
      }

      // Include row if EITHER GHL has a motivated tag OR ATTOM score > 0
      const isMotivated = hasMotivatedTag || (motivated && motivated.score > 0);
      if (!isMotivated) continue;

      const motivatedFlags: string[] = [];
      if (motivated?.absentee || embeddedTags.includes("absentee-owner")) motivatedFlags.push("absentee");
      if (motivated?.highEquity || embeddedTags.includes("high-equity")) motivatedFlags.push("high_equity");
      if (motivated?.recentTransfer || embeddedTags.includes("recent-transfer-probate")) motivatedFlags.push("recent_transfer");

      const ghlContactUrl = `https://app.gohighlevel.com/v2/location/${APG_LOCATION_ID}/contacts/detail/${contactId}`;
      const contactName = [contact.firstName, contact.lastName].filter(Boolean).join(" ") || (contact.contactName || "");

      // Compute MAO from ATTOM
      let mao: number | "" = "";
      if (attom?.avmValue) {
        const rehab = (attom.sqft || 0) * 30;
        mao = Math.max(0, Math.round(attom.avmValue * 0.70 - rehab - 10000));
      }

      rows.push([
        String(opp.id || ""),
        String(opp.pipelineStageId || opp.pipeline_stage_id || ""),
        contactName,
        String(contact.phone || ""),
        String(contact.email || ""),
        String(contact.address1 || ""),
        String(contact.city || ""),
        String(contact.state || ""),
        String(contact.postalCode || ""),
        motivatedFlags.join("|"),
        motivatedFlags.includes("absentee") ? "yes" : "",
        motivatedFlags.includes("high_equity") ? "yes" : "",
        motivatedFlags.includes("recent_transfer") ? "yes" : "",
        attom?.avmValue ? String(attom.avmValue) : "",
        attom?.avmLow   ? String(attom.avmLow)   : "",
        attom?.avmHigh  ? String(attom.avmHigh)  : "",
        attom?.avmConfidence != null ? String(attom.avmConfidence) : "",
        mao !== "" ? String(mao) : "",
        motivated?.equityAmount   ? String(Math.round(motivated.equityAmount))   : "",
        motivated?.equityMultiple ? motivated.equityMultiple.toFixed(2)          : "",
        attom?.beds  ? String(attom.beds)  : "",
        attom?.baths ? String(attom.baths) : "",
        attom?.sqft  ? String(attom.sqft)  : "",
        attom?.yearBuilt ? String(attom.yearBuilt) : "",
        attom?.lotAcres  ? attom.lotAcres.toFixed(2) : "",
        attom?.lastSaleAmt  ? String(attom.lastSaleAmt) : "",
        attom?.lastSaleDate ? String(attom.lastSaleDate).slice(0, 10) : "",
        attom?.assessedTotal ? String(attom.assessedTotal) : "",
        attom?.ownerName    ? String(attom.ownerName).trim() : "",
        attom?.ownerMailing && attom?.resolvedAddress &&
          !attom.ownerMailing.includes(attom.resolvedAddress.slice(0, 10))
          ? String(attom.ownerMailing) : "",
        ghlContactUrl,
      ]);
    }

    // Pagination cursor
    const meta = oppJson?.meta || {};
    if (opps.length < 50 || !meta.startAfter) break;
    startAfter   = meta.startAfter;
    startAfterId = meta.startAfterId;
  }

  // CSV escape: wrap in quotes if contains comma, quote, or newline; double internal quotes
  const escapeCsv = (s: string): string => {
    if (s.includes(",") || s.includes('"') || s.includes("\n") || s.includes("\r")) {
      return `"${s.replace(/"/g, '""')}"`;
    }
    return s;
  };
  const csv = rows.map((row) => row.map(escapeCsv).join(",")).join("\n");

  const filename = `motivated-sellers-${new Date().toISOString().slice(0, 10)}.csv`;
  return new Response(csv, {
    status: 200,
    headers: {
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="${filename}"`,
      "cache-control": "no-store",
    },
  });
}

// ---- ATTOM backfill of ACQ pipeline ----
// Iterates ACQ opps and enriches each contact + opp with ATTOM data.
// Run via /admin/attom/backfill (POST). Paginated — caller loops until
// the response has cursor:null.

async function handleAdminAttomBackfill(req: Request, env: Env): Promise<Response> {
  let body: any = {};
  try { body = await req.json(); } catch {}
  const batchSize = Math.max(1, Math.min(50, Number(body.batchSize) || 25));
  const startAfter   = body.startAfter   || undefined;
  const startAfterId = body.startAfterId || undefined;

  // 1. Fetch a page of opportunities in the ACQ pipeline.
  const params = new URLSearchParams({
    location_id: APG_LOCATION_ID,
    pipeline_id: ACQ_PIPELINE_ID,
    limit:       String(batchSize),
  });
  if (startAfter)   params.set("startAfter",   String(startAfter));
  if (startAfterId) params.set("startAfterId", String(startAfterId));
  const oppRes = await fetch(`${GHL_BASE}/opportunities/search?${params.toString()}`, {
    method: "GET", headers: ghlHeaders(env.BLAKE_GHL_PIT),
  });
  if (!oppRes.ok) {
    const t = await oppRes.text();
    return new Response(JSON.stringify({ error: `ghl_search_${oppRes.status}`, detail: t.slice(0, 300) }), {
      status: 502, headers: { "content-type": "application/json" },
    });
  }
  const oppJson: any = await oppRes.json();
  const opps: any[] = oppJson?.opportunities ?? [];
  const meta = oppJson?.meta || {};
  const nextCursor = (opps.length === batchSize && meta.startAfter)
    ? { startAfter: meta.startAfter, startAfterId: meta.startAfterId }
    : null;

  // 2. For each opp, fetch the contact's address + run ATTOM enrichment + write back.
  const results: any[] = [];
  for (const opp of opps) {
    const contactId = opp?.contact?.id || opp?.contactId;
    if (!contactId) { results.push({ oppId: opp.id, skipped: "no_contact" }); continue; }

    try {
      // Pull the full contact to get the address
      const contact = await getContactDetail(env.BLAKE_GHL_PIT, contactId);
      if (!contact) { results.push({ oppId: opp.id, skipped: "contact_fetch_failed" }); continue; }

      // Compose full address
      const addrParts = [contact.address1, contact.city, contact.state, contact.postalCode]
        .map((s: any) => String(s || "").trim())
        .filter(Boolean);
      const fullAddress = addrParts.join(", ");
      if (!fullAddress || addrParts.length < 2) {
        results.push({ oppId: opp.id, contactId, skipped: "no_address" });
        continue;
      }

      // ATTOM lookup (KV-cached)
      const attom = await enrichPropertyViaAttom(env, fullAddress);
      if (!attom || attom.error) {
        results.push({ oppId: opp.id, contactId, address: fullAddress, attom_error: attom?.error || "unknown" });
        continue;
      }

      // Write beds/baths/sqft onto the contact's custom fields
      const cfUpdates: Array<{ id: string; value: string }> = [];
      if (attom.beds)  cfUpdates.push({ id: CF_BEDS,  value: String(attom.beds)  });
      if (attom.baths) cfUpdates.push({ id: CF_BATHS, value: String(attom.baths) });
      if (attom.sqft)  cfUpdates.push({ id: CF_SQFT,  value: String(attom.sqft)  });
      if (cfUpdates.length > 0) {
        await updateContactFields(env.BLAKE_GHL_PIT, contactId, { customFields: cfUpdates }).catch(() => {});
      }

      // Compute MAO + update opp monetaryValue
      let computedMao: number | null = null;
      if (attom.avmValue && attom.sqft) {
        const rehab = attom.sqft * 30;  // MAO_REHAB_PER_SQFT
        computedMao = Math.max(0, Math.round(attom.avmValue * 0.70 - rehab - 10000));
      } else if (attom.avmValue) {
        computedMao = Math.max(0, Math.round(attom.avmValue * 0.70 - attom.avmValue * 0.12 - 10000));
      }
      if (computedMao !== null) {
        await fetch(`${GHL_BASE}/opportunities/${opp.id}`, {
          method: "PUT",
          headers: ghlHeaders(env.BLAKE_GHL_PIT),
          body: JSON.stringify({ monetaryValue: computedMao }),
        }).catch(() => {});
      }

      // Motivated-seller signals → tag the contact
      const signals = scoreMotivatedSignals(attom);
      if (signals.score > 0) {
        const tagSet: string[] = ["motivated-seller"];
        if (signals.absentee)       tagSet.push("absentee-owner");
        if (signals.highEquity)     tagSet.push("high-equity");
        if (signals.recentTransfer) tagSet.push("recent-transfer-probate");
        for (const t of tagSet) {
          await addTag(env.BLAKE_GHL_PIT, contactId, t).catch(() => {});
        }
      }

      results.push({
        oppId: opp.id, contactId,
        address: attom.resolvedAddress || fullAddress,
        avm: attom.avmValue, sqft: attom.sqft, beds: attom.beds, baths: attom.baths,
        mao: computedMao, score: signals.score, flags: signals.flags,
      });
    } catch (e: any) {
      results.push({ oppId: opp.id, error: String(e?.message || e) });
    }
  }

  const enriched = results.filter((r) => r.avm || r.beds).length;
  const skipped  = results.filter((r) => r.skipped).length;
  const errored  = results.filter((r) => r.error || r.attom_error).length;

  return new Response(JSON.stringify({
    processed: opps.length,
    enriched, skipped, errored,
    results,
    nextCursor,
  }, null, 2), {
    status: 200,
    headers: { "content-type": "application/json" },
  });
}

// Upload a remote image to the WP media library. Returns the new media ID.
async function uploadImageToWp(env: Env, sourceUrl: string, filenameSlug: string): Promise<number> {
  const imgRes = await fetch(sourceUrl);
  if (!imgRes.ok) throw new Error(`image fetch ${imgRes.status}`);
  const imgBytes = await imgRes.arrayBuffer();
  const contentType = imgRes.headers.get("content-type") || "image/jpeg";
  const ext = contentType.includes("png") ? "png" : "jpg";
  const filename = `${filenameSlug}-${Date.now()}.${ext}`;

  const uploadRes = await fetch(`${WP_REST_BASE}/media`, {
    method: "POST",
    headers: {
      "content-type": contentType,
      "content-disposition": `attachment; filename="${filename}"`,
      Authorization: env.WP_AUTH_HEADER,
    },
    body: imgBytes,
  });
  if (!uploadRes.ok) {
    const txt = await uploadRes.text();
    throw new Error(`wp media upload ${uploadRes.status}: ${txt.slice(0, 200)}`);
  }
  const j: any = await uploadRes.json();
  return j.id;
}

// ---- Pillar C: vault sync emitters + endpoint handlers --------------------
//
// vaultEmit(env, type, id, payload):
//   writes a single event into KV under `vault:queue:<iso>:<type>:<id>`. The
//   local Python daemon polls /vault/queue, writes markdown into APG-Vault,
//   and POSTs /vault/ack to delete the consumed keys.
//
// Event types currently emitted:
//   blake_call      — post-call webhook fires this with full transcript
//   landing_lead    — website form submission (handleLandingLead)
//   listing         — Pillar B listing-pipeline new offer
//   ghl_message     — new SMS / GHL conversation message (cron poller)
//
// Keys live in KV up to ~30 days (handler sets no expiration; daemon ack
// deletes them). If the daemon is offline for a stretch nothing is lost.

const VAULT_QUEUE_PREFIX = "vault:queue:";

async function vaultEmit(
  env: Env,
  type: string,
  id: string,
  payload: Record<string, any>
): Promise<void> {
  try {
    const iso = new Date().toISOString().replace(/[:.]/g, "-");
    const safeId = (id || "noid").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 80);
    const key = `${VAULT_QUEUE_PREFIX}${iso}:${type}:${safeId}`;
    const body = JSON.stringify({
      type,
      id,
      emitted_at: new Date().toISOString(),
      payload,
    });
    await env.DIAL_STATE.put(key, body);
  } catch (e) {
    // Never let a vault-emit failure break the upstream caller.
    console.error(`[vault-emit] type=${type} id=${id} failed: ${e}`);
  }
}

async function handleVaultQueueRead(env: Env, limit: number): Promise<Response> {
  // List up to `limit` keys with the vault-queue prefix. KV list is ordered
  // lexicographically — since we prefix with ISO timestamp, oldest-first.
  const listed = await env.DIAL_STATE.list({ prefix: VAULT_QUEUE_PREFIX, limit });
  const events: Array<{ key: string; event: any }> = [];
  // Read each value in parallel (KV list returns keys only).
  await Promise.all(
    listed.keys.map(async (k) => {
      try {
        const raw = await env.DIAL_STATE.get(k.name);
        if (!raw) return;
        events.push({ key: k.name, event: JSON.parse(raw) });
      } catch (e) {
        console.error(`[vault-queue] failed to read ${k.name}: ${e}`);
      }
    })
  );
  return new Response(
    JSON.stringify({
      ok: true,
      count: events.length,
      list_complete: listed.list_complete,
      events,
    }),
    { status: 200, headers: { "content-type": "application/json" } }
  );
}

async function handleVaultQueueAck(req: Request, env: Env): Promise<Response> {
  let body: any = {};
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ ok: false, error: "invalid_json" }), {
      status: 400,
      headers: { "content-type": "application/json" },
    });
  }
  const keys: string[] = Array.isArray(body?.keys) ? body.keys : [];
  if (!keys.length) {
    return new Response(JSON.stringify({ ok: true, deleted: 0 }), {
      status: 200,
      headers: { "content-type": "application/json" },
    });
  }
  // Only delete keys that actually have the vault prefix — defense in depth
  // so an ack call can never wipe other KV data even if mis-targeted.
  const safe = keys.filter((k) => typeof k === "string" && k.startsWith(VAULT_QUEUE_PREFIX));
  await Promise.all(safe.map((k) => env.DIAL_STATE.delete(k)));
  return new Response(
    JSON.stringify({ ok: true, deleted: safe.length, ignored: keys.length - safe.length }),
    { status: 200, headers: { "content-type": "application/json" } }
  );
}

// Normalize a GHL timestamp: GHL returns Unix ms numbers, but we store the
// cursor as an ISO string. Accept either form, return ms since epoch or NaN.
function toMs(v: any): number {
  if (typeof v === "number") return v;
  if (typeof v === "string") {
    if (/^\d+$/.test(v)) return Number(v);
    const p = Date.parse(v);
    return isFinite(p) ? p : NaN;
  }
  return NaN;
}

// Poll GHL for conversations updated in the recent window and emit one
// `ghl_message` vault event per message we haven't seen yet.
// Watermark stored at `vault:cursor:ghl_messages` as ISO timestamp.
async function pollGhlMessagesForVault(env: Env): Promise<void> {
  const CURSOR_KEY = "vault:cursor:ghl_messages";
  const SEEN_PREFIX = "vault:seen:msg:";
  const SEEN_TTL_S = 60 * 60 * 24 * 30; // 30 days
  const MAX_CONVERSATIONS = 30;          // cap per poll to keep latency bounded

  const cursor = (await env.DIAL_STATE.get(CURSOR_KEY)) || "";
  // Default look-back: last 30 min if no cursor.
  const sinceTs = cursor ? toMs(cursor) : Date.now() - 30 * 60 * 1000;
  if (!isFinite(sinceTs)) return;

  const res = await fetch(
    `${GHL_BASE}/conversations/search?` +
      new URLSearchParams({
        locationId: APG_LOCATION_ID,
        sortBy: "last_message_date",
        sort: "desc",
        limit: String(MAX_CONVERSATIONS),
      }).toString(),
    { headers: ghlHeaders(env.BLAKE_GHL_PIT) }
  );
  if (!res.ok) {
    console.warn(`[vault-ghl-poll] conversations/search ${res.status}`);
    return;
  }
  const j: any = await res.json();
  const convs: any[] = j?.conversations ?? [];
  let newestMs = isFinite(sinceTs) ? sinceTs : 0;
  let emitted = 0;

  for (const conv of convs) {
    const lastMs = toMs(conv?.lastMessageDate ?? conv?.dateUpdated);
    if (!isFinite(lastMs)) continue;
    // Stop scanning once we're past the cursor window (list is sorted desc).
    if (lastMs < sinceTs) break;
    if (lastMs > newestMs) newestMs = lastMs;

    const convId = conv?.id;
    if (!convId) continue;
    const msgsRes = await fetch(
      `${GHL_BASE}/conversations/${convId}/messages?limit=20`,
      { headers: ghlHeaders(env.BLAKE_GHL_PIT) }
    );
    if (!msgsRes.ok) continue;
    const msgsJ: any = await msgsRes.json();
    const messages: any[] = msgsJ?.messages?.messages ?? msgsJ?.messages ?? [];
    for (const m of messages) {
      const mMs = toMs(m?.dateAdded);
      if (!isFinite(mMs) || mMs < sinceTs) continue;
      const mId = m?.id;
      if (!mId) continue;
      const seenKey = `${SEEN_PREFIX}${mId}`;
      const seen = await env.DIAL_STATE.get(seenKey);
      if (seen) continue;
      await env.DIAL_STATE.put(seenKey, "1", { expirationTtl: SEEN_TTL_S });
      await vaultEmit(env, "ghl_message", mId, {
        conversation_id: convId,
        contact_id: conv?.contactId || "",
        contact_name: conv?.fullName || conv?.contactName || "",
        contact_phone: conv?.phone || "",
        direction: m?.direction || "",
        message_type: m?.messageType || m?.type || "",
        body: m?.body || m?.message || "",
        date_added: new Date(mMs).toISOString(),
      });
      emitted++;
    }
  }

  if (newestMs > toMs(cursor) || !cursor) {
    await env.DIAL_STATE.put(CURSOR_KEY, new Date(newestMs).toISOString());
  }
  console.log(`[vault-ghl-poll] scanned ${convs.length} convs, emitted ${emitted} messages, cursor → ${new Date(newestMs).toISOString()}`);
}

// ---- Self-improvement: Claude reviews recent Blake calls --------------------
//
// Gathers the N most-recent Blake conversations from ElevenLabs (where we have
// raw transcripts), summarizes patterns, and proposes targeted edits to the
// SMS / voice prompt. Output gets written to APG-Vault via vault event:
//
//   _system/Blake/iterations/YYYY-MM-DD-analysis.md
//
// We do NOT auto-swap the prompt. Mido reviews, then promotes manually.

async function runBlakeSelfImprovement(env: Env, sampleSize: number): Promise<{
  ok: boolean;
  analyzed: number;
  error?: string;
}> {
  if (!env.ANTHROPIC_API_KEY) {
    return { ok: false, analyzed: 0, error: "ANTHROPIC_API_KEY not bound" };
  }
  if (!env.ELEVENLABS_API_KEY) {
    return { ok: false, analyzed: 0, error: "ELEVENLABS_API_KEY not bound" };
  }

  // 1. Pull the N most-recent conversations from ElevenLabs.
  const listRes = await fetch(
    `https://api.elevenlabs.io/v1/convai/conversations?agent_id=${BLAKE_AGENT_ID}&page_size=${Math.min(sampleSize, 100)}`,
    { headers: { "xi-api-key": env.ELEVENLABS_API_KEY } }
  );
  if (!listRes.ok) {
    return { ok: false, analyzed: 0, error: `elevenlabs list ${listRes.status}` };
  }
  const listJson: any = await listRes.json();
  const conversations: any[] = (listJson?.conversations || []).slice(0, sampleSize);
  if (!conversations.length) {
    return { ok: false, analyzed: 0, error: "no conversations available" };
  }

  // 2. Hydrate each with its transcript.
  const samples: Array<{ id: string; phone: string; duration: number; summary: string; turns: string }> = [];
  for (const c of conversations) {
    const convId = c?.conversation_id || c?.id;
    if (!convId) continue;
    const det = await fetch(
      `https://api.elevenlabs.io/v1/convai/conversations/${convId}`,
      { headers: { "xi-api-key": env.ELEVENLABS_API_KEY } }
    );
    if (!det.ok) continue;
    const d: any = await det.json();
    const turns: any[] = d?.transcript ?? [];
    const text = turns
      .slice(0, 30)
      .map((t) => {
        const role = (t.role || "?").toUpperCase();
        const msg = (t.message || t.content || "").trim();
        return msg ? `[${role}] ${msg}` : "";
      })
      .filter(Boolean)
      .join("\n");
    if (!text) continue;
    samples.push({
      id: convId,
      phone: d?.metadata?.phone_call?.external_number || "?",
      duration: d?.metadata?.call_duration_secs || 0,
      summary: d?.analysis?.transcript_summary || "",
      turns: text,
    });
  }

  if (!samples.length) {
    return { ok: false, analyzed: 0, error: "no transcripts to analyze" };
  }

  // 3. Ask Claude to extract patterns + propose targeted edits.
  const systemPrompt = `You are an SDR coach reviewing recent calls made by "Blake", APG's AI voice agent. Your job: spot recurring failure modes and propose specific, surgical edits to Blake's system prompt. Be concrete. Avoid platitudes.

Output STRICT markdown matching this skeleton:

# Blake call review — {{YYYY-MM-DD}}

## Sample
- Calls analyzed: N
- Avg duration: X sec
- Outcomes: short list

## Failure modes (top 3)
1. **Name** — what went wrong, frequency (X of N calls), one transcript snippet as evidence.
2. ...
3. ...

## Working behaviors (top 3)
1. **Name** — example snippet.

## Proposed prompt edits
For each edit, give: (a) section/heading to modify, (b) current line(s), (c) proposed replacement, (d) why.

## Risks
Anything the proposed edits might break.`;

  const userPrompt = `Sample of ${samples.length} recent Blake calls.

${samples.map((s, i) => `--- Call ${i + 1} (id=${s.id} phone=${s.phone} duration=${s.duration}s)
Summary: ${s.summary || "(none)"}
Transcript (first 30 turns):
${s.turns}
`).join("\n")}

Produce the review now. Markdown only, no preamble.`;

  const aRes = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "x-api-key": env.ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: "claude-opus-4-7",
      max_tokens: 4000,
      system: systemPrompt,
      messages: [{ role: "user", content: userPrompt }],
    }),
  });
  if (!aRes.ok) {
    const t = await aRes.text();
    return { ok: false, analyzed: samples.length, error: `claude ${aRes.status}: ${t.slice(0, 200)}` };
  }
  const aJson: any = await aRes.json();
  const reviewMd: string = (aJson?.content?.[0]?.text || "").trim();
  if (!reviewMd) {
    return { ok: false, analyzed: samples.length, error: "claude returned empty body" };
  }

  // 4. Emit vault event so the daemon writes it into iterations/.
  await vaultEmit(env, "blake_iteration", `selfimprove-${Date.now()}`, {
    sample_size: samples.length,
    avg_duration_s: Math.round(samples.reduce((a, s) => a + s.duration, 0) / samples.length),
    review_markdown: reviewMd,
    sample_ids: samples.map((s) => s.id),
  });

  // 5. Workstream 6 followup — write the latest-pointer KV so the dashboard's
  //    "What Blake can improve on" cards have data to read. Previously the
  //    section always rendered the empty-state placeholder because nothing
  //    populated this key.
  await env.DIAL_STATE.put(
    "blake:iteration:latest",
    JSON.stringify({
      generated_at: new Date().toISOString(),
      review_markdown: reviewMd,
      sample_size: samples.length,
    }),
    { expirationTtl: 60 * 60 * 24 * 14 }   // 14d — next review supersedes
  );

  return { ok: true, analyzed: samples.length };
}

// ---- Daily Slack summary -----------------------------------------------------
//
// Posts yesterday's activity digest to #base1-sms-leadgen.
//   - Blake calls (count, hot/warm leads, longest)
//   - Landing leads (count, sources)
//   - Listings (count, MAOs)
//   - GHL inbound messages (top 5 with reply pending)
async function runDailySlackSummary(env: Env): Promise<{ ok: boolean; posted: boolean; error?: string }> {
  if (!env.SLACK_BOT_TOKEN) return { ok: false, posted: false, error: "no SLACK_BOT_TOKEN" };

  const now = new Date();
  const yesterdayMs = Date.now() - 24 * 3600 * 1000;
  const yesterdayLabel = new Date(yesterdayMs).toISOString().slice(0, 10);

  // 1. Blake calls — list ElevenLabs convs in the last 24h.
  let blakeCalls = 0;
  let blakeLongestS = 0;
  let blakeTotalS = 0;
  try {
    if (env.ELEVENLABS_API_KEY) {
      const lr = await fetch(
        `https://api.elevenlabs.io/v1/convai/conversations?agent_id=${BLAKE_AGENT_ID}&page_size=50`,
        { headers: { "xi-api-key": env.ELEVENLABS_API_KEY } }
      );
      if (lr.ok) {
        const lj: any = await lr.json();
        for (const c of (lj?.conversations || [])) {
          const startedMs = (c?.start_time_unix_secs || 0) * 1000;
          if (startedMs < yesterdayMs || startedMs > Date.now()) continue;
          blakeCalls++;
          const d = c?.call_duration_secs || 0;
          blakeTotalS += d;
          if (d > blakeLongestS) blakeLongestS = d;
        }
      }
    }
  } catch (e) {
    console.warn(`[daily-summary] blake fetch failed: ${e}`);
  }

  // 2. GHL inbound message count in the last 24h.
  let inboundCount = 0;
  let outboundCount = 0;
  try {
    const cr = await fetch(
      `${GHL_BASE}/conversations/search?` +
        new URLSearchParams({
          locationId: APG_LOCATION_ID,
          sortBy: "last_message_date",
          sort: "desc",
          limit: "50",
        }).toString(),
      { headers: ghlHeaders(env.BLAKE_GHL_PIT) }
    );
    if (cr.ok) {
      const cj: any = await cr.json();
      for (const cv of (cj?.conversations || [])) {
        const lastMs = toMs(cv?.lastMessageDate);
        if (!isFinite(lastMs) || lastMs < yesterdayMs) continue;
        const dir = cv?.lastMessageDirection || "";
        if (dir === "inbound") inboundCount++;
        else if (dir === "outbound") outboundCount++;
      }
    }
  } catch (e) {
    console.warn(`[daily-summary] ghl fetch failed: ${e}`);
  }

  // Audit 1.1 warmup alert — compare yesterday's actual dial count vs that
  // day's quota. The dialer accumulated 298 dials of debt before anyone
  // noticed because no daily floor check existed. Threshold: <70% of quota
  // = WARN, <40% = CRIT. Posts inline with the daily summary.
  let warmupAlertLine = "";
  try {
    const yesterday = new Date(yesterdayMs);
    const yDayIdx = await dayIndexFromAnchor(env, yesterday);
    const yQuota = quotaForDay(yDayIdx);
    const yDateKey = utcDateString(yesterday);
    const yDialedRaw = await env.DIAL_STATE.get(`dialed:${yDateKey}`);
    const yDialed = yDialedRaw ? parseInt(yDialedRaw, 10) || 0 : 0;
    if (yQuota > 0) {
      const pct = Math.round((yDialed / yQuota) * 100);
      const debt = Math.max(0, yQuota - yDialed);
      if (pct < 40) {
        warmupAlertLine = `:rotating_light: *Warm-up CRITICAL* — only ${yDialed}/${yQuota} dials yesterday (${pct}%). Debt: *${debt}*. Picker is starving — investigate.\n`;
      } else if (pct < 70) {
        warmupAlertLine = `:warning: *Warm-up under floor* — ${yDialed}/${yQuota} dials yesterday (${pct}%). Debt: *${debt}*. Pool may be drying.\n`;
      }
    }
  } catch (e) {
    console.warn(`[warmup-alert] check failed: ${e}`);
  }

  const avgDur = blakeCalls ? Math.round(blakeTotalS / blakeCalls) : 0;
  const text =
    `:sunrise: *APG daily — ${yesterdayLabel}*\n` +
    warmupAlertLine +
    `:phone: Blake calls: *${blakeCalls}*` +
    (blakeCalls ? ` (avg ${avgDur}s, longest ${blakeLongestS}s)` : "") + `\n` +
    `:speech_balloon: GHL conversations updated: *${inboundCount + outboundCount}* (inbound ${inboundCount}, outbound ${outboundCount})\n` +
    `:link: <https://acq-automation.mithchell.workers.dev/blake.html|live dashboard> · <https://acq-automation.mithchell.workers.dev/insights|website insights>`;

  const slack = await postSlackMessage(env, SLACK_ALERTS_CHANNEL, text);
  return { ok: true, posted: slack.ok, error: slack.ok ? undefined : `slack ${slack.status}` };
}

// ---- Workstream PR C: per-agent activity + Claude review --------------------
//
// For each agent in APG_AGENT_ROSTER, pull last 7 days of:
//   - opportunities currently assigned to them
//   - opportunities where they moved a stage (best-effort via dateUpdated)
//   - outbound conversation messages they sent
// Aggregate → KV `agent:activity:<user_id>:weekly`.
// Then ask Opus 4.7 for a short "what should have gone better" review per
// agent → KV `agent:review:<user_id>:latest` + vault event `agent_review`.
// Slack teaser posts to #apg-alerts when reviews land.

interface AgentWeeklyActivity {
  user_id: string;
  name: string;
  role: string;
  window_start: string;     // ISO
  window_end: string;       // ISO
  opps_assigned: number;
  opps_moved: number;       // opps with dateUpdated in window AND assignedTo matches
  outbound_msgs: number;
  property_addresses: string[];   // unique addresses connected to via opps
  stalled_opps: Array<{ id: string; name: string; days_since_update: number }>;
  generated_at: string;
}

async function aggregateAgentActivity(
  env: Env,
  user: { user_id: string; name: string; role: string },
  windowDays: number = 7
): Promise<AgentWeeklyActivity> {
  const now = Date.now();
  const sinceMs = now - windowDays * 24 * 3600 * 1000;
  const windowStart = new Date(sinceMs).toISOString();
  const windowEnd   = new Date(now).toISOString();

  const out: AgentWeeklyActivity = {
    user_id: user.user_id,
    name: user.name,
    role: user.role,
    window_start: windowStart,
    window_end: windowEnd,
    opps_assigned: 0,
    opps_moved: 0,
    outbound_msgs: 0,
    property_addresses: [],
    stalled_opps: [],
    generated_at: new Date().toISOString(),
  };

  // 1. Opportunities assigned to this user. Capped at 3 pages = 300 opps
  // to stay under CF Worker's 50-subrequest cap per invocation (2 agents
  // × 3 opp pages + 1 conv scan = ~7 subrequests/agent, well under).
  try {
    let page = 1;
    const addresses = new Set<string>();
    while (page <= 3) {
      const res = await fetch(
        `${GHL_BASE}/opportunities/search?` +
          new URLSearchParams({
            location_id: APG_LOCATION_ID,
            assignedTo: user.user_id,
            limit: "100",
            page: String(page),
          }).toString(),
        { headers: ghlHeaders(env.BLAKE_GHL_PIT) }
      );
      if (!res.ok) break;
      const j: any = await res.json();
      const opps: any[] = j?.opportunities ?? [];
      if (!opps.length) break;
      for (const o of opps) {
        out.opps_assigned += 1;
        const updMs = toMs(o?.updatedAt || o?.dateUpdated || o?.updated_at);
        if (isFinite(updMs) && updMs >= sinceMs) out.opps_moved += 1;
        const daysSince = isFinite(updMs) ? (now - updMs) / (24 * 3600 * 1000) : 999;
        if ((o?.status || "open") === "open" && daysSince >= 21) {
          out.stalled_opps.push({
            id: o?.id || "",
            name: o?.name || "",
            days_since_update: Math.round(daysSince),
          });
        }
        const nm = (o?.name || "").trim();
        const parts = nm.split(" - ").map((s: string) => s.trim());
        if (parts.length >= 2 && parts[1]) addresses.add(parts[1]);
      }
      if (opps.length < 100) break;
      page += 1;
    }
    out.property_addresses = Array.from(addresses).slice(0, 50);
    out.stalled_opps.sort((a, b) => b.days_since_update - a.days_since_update);
    out.stalled_opps = out.stalled_opps.slice(0, 10);
  } catch (e) {
    console.warn(`[agent-aggregate] opp search failed for ${user.name}: ${e}`);
  }

  // 2. Outbound conversation count — single scan of recent conversations,
  // NO per-conversation message fetch (that was the subrequest-budget
  // killer). Uses `lastOutboundMessageAction === "manual"` + assignedTo
  // as the best available proxy for "this agent sent something."
  try {
    const cr = await fetch(
      `${GHL_BASE}/conversations/search?` +
        new URLSearchParams({
          locationId: APG_LOCATION_ID,
          assignedTo: user.user_id,
          sortBy: "last_message_date",
          sort: "desc",
          limit: "30",
        }).toString(),
      { headers: ghlHeaders(env.BLAKE_GHL_PIT) }
    );
    if (cr.ok) {
      const cj: any = await cr.json();
      for (const cv of (cj?.conversations || [])) {
        const lastMs = toMs(cv?.lastMessageDate);
        if (!isFinite(lastMs) || lastMs < sinceMs) continue;
        if (cv?.lastMessageDirection === "outbound" && cv?.lastOutboundMessageAction === "manual") {
          out.outbound_msgs += 1;
        }
      }
    }
  } catch (e) {
    console.warn(`[agent-aggregate] msg scan failed for ${user.name}: ${e}`);
  }

  // 3. Persist the snapshot.
  await env.DIAL_STATE.put(
    `agent:activity:${user.user_id}:weekly`,
    JSON.stringify(out),
    { expirationTtl: 60 * 60 * 24 * 14 }   // keep 2 weeks of history per key rev
  );
  return out;
}

async function runAgentAiReview(env: Env, activity: AgentWeeklyActivity): Promise<{
  ok: boolean;
  review_md?: string;
  error?: string;
}> {
  if (!env.ANTHROPIC_API_KEY) return { ok: false, error: "ANTHROPIC_API_KEY not bound" };

  const systemPrompt = `You are an SDR coach reviewing one APG team member's last 7 days of CRM activity. Be concrete and actionable — no platitudes. Cite specific opp/address evidence from the data. Output STRICT markdown:

# {{Name}} — week of {{YYYY-MM-DD}}

## Snapshot
- Opps assigned: N
- Opps moved (touched): N
- Outbound messages: N
- Properties connected: N unique
- Stalled opps (>21d no update): N

## What went well (top 2)
1. **Theme** — short evidence
2. **Theme** — short evidence

## What should have gone better (top 3)
1. **Theme** — short evidence + specific recommendation
2. ...
3. ...

## Stalled opps needing attention this week
- {{opp name}} ({{days}}d stale) — suggested next step

## Suggested focus for next week
One sentence.`;

  const userPrompt = `Activity for ${activity.name} (${activity.role}) from ${activity.window_start} to ${activity.window_end}:

- Opps assigned: ${activity.opps_assigned}
- Opps moved (updated in window): ${activity.opps_moved}
- Outbound messages sent: ${activity.outbound_msgs}
- Unique properties connected to: ${activity.property_addresses.length}

Top stalled opps:
${activity.stalled_opps.length === 0 ? "(none)" : activity.stalled_opps.map((o) => `- ${o.name} (${o.days_since_update}d stale)`).join("\n")}

Recent properties connected:
${activity.property_addresses.slice(0, 15).map((a) => `- ${a}`).join("\n") || "(none)"}

Produce the review now. Markdown only, no preamble.`;

  const r = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "x-api-key": env.ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      // Opus 4.7 deprecated the `temperature` field (per API error 400 on
      // 2026-05-27). Omit it.
      model: "claude-opus-4-7",
      max_tokens: 3000,
      system: systemPrompt,
      messages: [{ role: "user", content: userPrompt }],
    }),
  });
  if (!r.ok) {
    const t = await r.text();
    return { ok: false, error: `claude ${r.status}: ${t.slice(0, 200)}` };
  }
  const data: any = await r.json();
  const md = (data?.content?.[0]?.text || "").trim();
  if (!md) return { ok: false, error: "empty review" };

  // Persist + emit vault event.
  const record = { generated_at: new Date().toISOString(), review_md: md, activity };
  await env.DIAL_STATE.put(
    `agent:review:${activity.user_id}:latest`,
    JSON.stringify(record)
  );
  await vaultEmit(env, "agent_review", activity.user_id, {
    user_id: activity.user_id,
    name: activity.name,
    role: activity.role,
    review_markdown: md,
    activity_snapshot: activity,
  });

  return { ok: true, review_md: md };
}

async function runAllAgentReviews(env: Env): Promise<{
  ok: boolean;
  reviewed: number;
  errors: string[];
}> {
  const out = { ok: true, reviewed: 0, errors: [] as string[] };
  for (const u of APG_AGENT_ROSTER) {
    try {
      const activity = await aggregateAgentActivity(env, u);
      const r = await runAgentAiReview(env, activity);
      if (r.ok) out.reviewed += 1;
      else out.errors.push(`${u.name}: ${r.error}`);
    } catch (e: any) {
      out.errors.push(`${u.name} threw: ${String(e?.message || e).slice(0, 100)}`);
    }
  }
  // Slack teaser
  if (env.SLACK_BOT_TOKEN && out.reviewed > 0) {
    const teaser =
      `:notebook: *Agent reviews refreshed* — ${out.reviewed}/${APG_AGENT_ROSTER.length} agents reviewed\n` +
      `Open the dashboard's Agents tab to read: https://acq-automation.mithchell.workers.dev/dashboard#agents`;
    await postSlackMessage(env, SLACK_ALERTS_CHANNEL, teaser).catch(() => {});
  }
  return out;
}

// ---- Workstream 2: Google Places proxy + SMS variants + RJ task --------------
//
// All 3 landing-lead enhancements landed together because they share state
// (the form payload + the contact upsert flow). Form HTML changes live in
// APG-Vault/_internal/website-v2/push_zip_pages.py and need a re-push after
// this PR deploys.

const CORS_HEADERS_PLACES: Record<string, string> = {
  // The form lives on atompropertygroup.com but we also allow the Worker's own
  // origin (for /insights and similar) and any sub-path testing.
  "access-control-allow-origin":  "*",
  "access-control-allow-methods": "GET, OPTIONS",
  "access-control-allow-headers": "content-type",
  "cache-control":                "public, max-age=300",
};

async function handlePlacesAutocomplete(req: Request, env: Env): Promise<Response> {
  if (!env.GOOGLE_PLACES_API_KEY) {
    return new Response(JSON.stringify({ ok: false, error: "GOOGLE_PLACES_API_KEY not configured" }), {
      status: 503, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
    });
  }
  const url = new URL(req.url);
  const input = (url.searchParams.get("input") || "").trim();
  if (input.length < 3) {
    return new Response(JSON.stringify({ ok: true, predictions: [] }), {
      status: 200, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
    });
  }
  // Use the legacy Places Autocomplete endpoint — wider compatibility, lower
  // latency than the new v1 endpoint for this address-only use case. US-only.
  const gUrl =
    "https://maps.googleapis.com/maps/api/place/autocomplete/json?" +
    new URLSearchParams({
      input,
      types: "address",
      components: "country:us",
      key: env.GOOGLE_PLACES_API_KEY,
    }).toString();
  const res = await fetch(gUrl);
  if (!res.ok) {
    const t = await res.text();
    console.warn(`[places-autocomplete] ${res.status}: ${t.slice(0, 200)}`);
    return new Response(JSON.stringify({ ok: false, error: `google_${res.status}` }), {
      status: 502, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
    });
  }
  const j: any = await res.json();
  // Pass back ONLY the fields the client needs — never the raw Google response,
  // so we can revisit the upstream API without affecting the form.
  const predictions = (j?.predictions || []).map((p: any) => ({
    place_id:    p.place_id,
    description: p.description,
    main_text:   p.structured_formatting?.main_text || "",
    secondary:   p.structured_formatting?.secondary_text || "",
  }));
  return new Response(JSON.stringify({ ok: true, predictions }), {
    status: 200, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
  });
}

async function handlePlacesDetails(req: Request, env: Env): Promise<Response> {
  if (!env.GOOGLE_PLACES_API_KEY) {
    return new Response(JSON.stringify({ ok: false, error: "GOOGLE_PLACES_API_KEY not configured" }), {
      status: 503, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
    });
  }
  const url = new URL(req.url);
  const placeId = (url.searchParams.get("place_id") || "").trim();
  if (!placeId) {
    return new Response(JSON.stringify({ ok: false, error: "missing place_id" }), {
      status: 400, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
    });
  }
  const gUrl =
    "https://maps.googleapis.com/maps/api/place/details/json?" +
    new URLSearchParams({
      place_id: placeId,
      fields:   "address_components,formatted_address,geometry/location,place_id",
      key:      env.GOOGLE_PLACES_API_KEY,
    }).toString();
  const res = await fetch(gUrl);
  if (!res.ok) {
    const t = await res.text();
    console.warn(`[places-details] ${res.status}: ${t.slice(0, 200)}`);
    return new Response(JSON.stringify({ ok: false, error: `google_${res.status}` }), {
      status: 502, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
    });
  }
  const j: any = await res.json();
  const r = j?.result;
  if (!r) {
    return new Response(JSON.stringify({ ok: false, error: "no_result" }), {
      status: 404, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
    });
  }
  // Flatten address_components into the GHL contact field shape so the
  // browser side has nothing to interpret. street_number + route → address1.
  const comps: Array<{ types: string[]; long_name: string; short_name: string }> = r.address_components || [];
  const pick = (t: string, short = false): string => {
    const c = comps.find((x) => x.types.includes(t));
    return c ? (short ? c.short_name : c.long_name) : "";
  };
  const streetNumber = pick("street_number");
  const route        = pick("route");
  const address1     = [streetNumber, route].filter(Boolean).join(" ") || r.formatted_address || "";
  return new Response(JSON.stringify({
    ok: true,
    place_id:        r.place_id,
    formatted:       r.formatted_address || "",
    address1,
    city:            pick("locality") || pick("sublocality") || pick("administrative_area_level_3"),
    state:           pick("administrative_area_level_1", true),
    postal_code:     pick("postal_code"),
    country:         pick("country", true),
    latitude:        r.geometry?.location?.lat ?? null,
    longitude:       r.geometry?.location?.lng ?? null,
  }), {
    status: 200, headers: { "content-type": "application/json", ...CORS_HEADERS_PLACES },
  });
}

// 3 SMS variants — Friendly default. Variant chosen by form field `variant`
// (or cookie `apg_variant` on a future request). All from +1 609-699-8437 via
// the GHL Conversations API (sendGhlSms wrapper).
type LandingLeadVariant = "friendly" | "professional" | "traditional";

function landingLeadSmsBody(variant: LandingLeadVariant, firstName: string, address: string): string {
  const first = (firstName || "there").trim();
  const addr  = (address || "your property").trim();
  switch (variant) {
    case "professional":
      return `Hi ${first}, Mike with APG confirming we received your inquiry on ${addr}. Our team will follow up within 60 minutes with a cash offer range.`;
    case "traditional":
      return `Hello ${first}, this is Mike from Atom Property Group regarding your inquiry on ${addr}. Expect a call from our team within the hour.`;
    case "friendly":
    default:
      return `Hey ${first}, Mike with APG — got your form for ${addr}. RJ will text within the hour with our cash range. Looking forward to it.`;
  }
}

function pickLandingLeadVariant(req: Request, fields: Record<string, string>): LandingLeadVariant {
  // Priority: explicit form field > apg_variant cookie > friendly default.
  const raw = (fields["variant"] || readCookie(req, "apg_variant") || "").toLowerCase();
  if (raw === "professional" || raw === "traditional" || raw === "friendly") return raw;
  return "friendly";
}

function readCookie(req: Request, name: string): string {
  const h = req.headers.get("cookie") || "";
  const m = h.match(new RegExp(`(?:^|;\\s*)${name}=([^;]+)`));
  return m ? decodeURIComponent(m[1]) : "";
}

// ===========================================================================
// Slice I (P0) — Qualified stage real-time alerts + RJ auto-task
//
// Audit 1.6 found 19 Qualified opps idle 19-27 days with no human owner. The
// chain "Seller replies → moved to Qualified → human notified" was broken at
// the last step.
//
// pollQualifiedStageAlerts(env):
//   1. Lists every opp currently in STAGE_QUALIFIED
//   2. For each opp seen for the first time (no `alert:qualified:<oppId>` KV):
//      a. Posts a Slack alert to SLACK_ALERTS_CHANNEL with name, address,
//         phone, last update, last reply body, contact tags
//      b. Creates a GHL task on the contact, assigned to RJ, due 1h from now
//      c. Writes `alert:qualified:<oppId>` to KV with the task ID + sent_at
//   3. For each existing alert older than 4h with no task completion + opp
//      still in Qualified: creates an ESCALATION task to Mike
//
// Runs on the */15 cron tick. Latency: ~15 min worst case from opp entering
// Qualified to Slack alert. Good enough for P0; can shorten to */5 later.
// ===========================================================================

// 2026-05-27 directive: alert when an opp lands in ANY of the 5 "hot" stages
// (Qualified → LAO → Due Diligence → Negotiate → Contract Sent). Per-stage
// SLA: Qualified gets the full RJ-task + Mike-escalation; stages 2-5 get an
// informational ping only (RJ already owns those opps; no SLA timer needed).
async function pollQualifiedStageAlerts(env: Env): Promise<void> {
  const nowMs = Date.now();
  let alertsSent = 0;
  let tasksCreated = 0;
  let escalationsSent = 0;

  for (const stage of HOT_PIPELINE_STAGES) {
    // Per-stage KV prefix so the same opp moving through Qualified → LAO →
    // Negotiate each generates its own alert (one per stage entry).
    const stageShort = stage.id.slice(0, 8);
    const KV_PREFIX  = `alert:stage:${stageShort}:`;
    const ESC_PREFIX = `alert:stage-esc:${stageShort}:`;

    // 1. Pull opps in this stage (capped at 50).
    const r = await fetch(
      `${GHL_BASE}/opportunities/search?` +
        new URLSearchParams({
          location_id: APG_LOCATION_ID,
          pipeline_id: ACQ_PIPELINE_ID,
          pipeline_stage_id: stage.id,
          limit: "50",
        }).toString(),
      { headers: ghlHeaders(env.BLAKE_GHL_PIT) }
    );
    if (!r.ok) {
      console.warn(`[hot-alerts] search failed for ${stage.label}: ${r.status}`);
      continue;
    }
    const j: any = await r.json();
    const opps: any[] = j?.opportunities ?? [];

    for (const opp of opps) {
      const oppId = opp?.id;
      if (!oppId) continue;
      const contact = opp?.contact || {};
      const contactId = contact?.id;
      if (!contactId) continue;

      const alertKey = `${KV_PREFIX}${oppId}`;
      const existing = await env.DIAL_STATE.get(alertKey);

      if (!existing) {
        // ---- FIRST-TIME ALERT FOR THIS (stage, opp) PAIR ----
        try {
          const name = contact.name || contact.contactName || "(unknown)";
          const phone = contact.phone || "";
          const oppName = (opp?.name || "").trim();
          const sep = oppName.includes(" - ") ? " - " : " / ";
          const parts = oppName.split(sep).map((s: string) => s.trim());
          const address = parts[1] || "(unknown address)";
          const tags: string[] = contact.tags || [];
          const repliedTag = tags.includes("customer replied");
          const updatedAt = opp?.updatedAt || opp?.dateUpdated || "";
          const updatedDisp = updatedAt ? new Date(updatedAt).toLocaleString() : "?";

          const ghlOppUrl = `https://app.gohighlevel.com/v2/location/${APG_LOCATION_ID}/opportunities/list?status=open&opportunityId=${oppId}`;

          let slackText: string;
          if (stage.sla === "rj_1h") {
            slackText =
              `:rotating_light: *${stage.label}* — ${name}\n` +
              `> *Address:* ${address}\n` +
              `> *Phone:* ${phone || "—"}\n` +
              `> *Last update:* ${updatedDisp}\n` +
              `> *Tags:* ${tags.slice(0, 8).join(", ") || "—"}\n` +
              (repliedTag ? `> :speech_balloon: Seller has actively REPLIED — high intent.\n` : "") +
              `> *Action:* RJ has 1 hour to call. Mike escalation auto-fires at 4h if no completion.\n` +
              `> <${ghlOppUrl}|Open in GHL>`;
          } else {
            // Informational ping for stages 2-5 (LAO / Due Diligence / Negotiate / Contract Sent)
            slackText =
              `:incoming_envelope: *${stage.label}* — ${name}\n` +
              `> *Address:* ${address}\n` +
              `> *Phone:* ${phone || "—"}\n` +
              `> *Last update:* ${updatedDisp}\n` +
              `> <${ghlOppUrl}|Open in GHL>`;
          }
          const slack = await postSlackMessage(env, SLACK_ALERTS_CHANNEL, slackText);
          if (slack.ok) alertsSent++;

          let taskId = "";
          let taskOk = false;
          if (stage.sla === "rj_1h") {
            // Stage 1 only: create RJ task with 1h due date.
            const dueDate = new Date(nowMs + 60 * 60 * 1000).toISOString();
            const t = await createTaskOnContact(env.BLAKE_GHL_PIT, contactId, {
              title: `🔥 Call ${name} — ${stage.label} (1h SLA)`,
              body: [
                `Seller moved to ${stage.label}.`,
                `Address: ${address}`,
                `Phone: ${phone || "(missing — pull from contact)"}`,
                `Tags: ${tags.join(", ")}`,
                `Opp ID: ${oppId}`,
                ``,
                `1-hour SLA. Mike escalation at ${dueDate}.`,
              ].join("\n"),
              dueDate,
              assignedTo: USER_RJ,
            });
            taskOk = t.ok;
            taskId = (t as any).taskId || "";
            if (taskOk) tasksCreated++;
          }

          await env.DIAL_STATE.put(alertKey, JSON.stringify({
            alerted_at: new Date().toISOString(),
            stage_id: stage.id,
            stage_label: stage.label,
            slack_ok: slack.ok,
            task_id: taskId,
            task_ok: taskOk,
          }), { expirationTtl: 60 * 60 * 24 * 30 });

          // Funnel event: stage entry detected by this poller.
          const evType = stageToFunnelEvent(stage.id);
          if (evType) {
            await recordFunnelEvent(env, {
              type: evType,
              opp_id: oppId,
              contact_id: contactId,
              stage_to: stage.id,
              source: "hot_pipeline_poller",
              metadata: { stage_label: stage.label, has_replied_tag: repliedTag },
            });
          }
        } catch (e) {
          console.warn(`[hot-alerts] alert failed for opp ${oppId} stage ${stage.label}: ${e}`);
        }
      } else if (stage.sla === "rj_1h") {
        // ---- ESCALATION CHECK (Qualified only) ----
        try {
          const meta = JSON.parse(existing);
          const alertedMs = Date.parse(meta?.alerted_at || "") || 0;
          const hoursSince = (nowMs - alertedMs) / (1000 * 60 * 60);
          const escKey = `${ESC_PREFIX}${oppId}`;
          const escSent = await env.DIAL_STATE.get(escKey);
          if (hoursSince >= 4 && !escSent) {
            const name = contact.name || contact.contactName || "(unknown)";
            const oppName = (opp?.name || "").trim();
            const sep = oppName.includes(" - ") ? " - " : " / ";
            const address = (oppName.split(sep)[1] || "").trim();
            const phone = contact.phone || "";

            const ghlOppUrl = `https://app.gohighlevel.com/v2/location/${APG_LOCATION_ID}/opportunities/list?status=open&opportunityId=${oppId}`;
            const slackText =
              `:warning: *4-HOUR ESCALATION* — ${name} still in ${stage.label}, no RJ action\n` +
              `> *Address:* ${address}\n` +
              `> *Phone:* ${phone || "—"}\n` +
              `> *Alerted to RJ:* ${meta.alerted_at}\n` +
              `> *Action:* Mike — please call or reassign.\n` +
              `> <${ghlOppUrl}|Open in GHL>`;
            await postSlackMessage(env, SLACK_ALERTS_CHANNEL, slackText).catch(() => {});

            const escDue = new Date(nowMs + 60 * 60 * 1000).toISOString();
            await createTaskOnContact(env.BLAKE_GHL_PIT, contactId, {
              title: `⚠ ESCALATION — RJ didn't act on ${name} in 4h`,
              body: [
                `RJ was assigned a ${stage.label} task at ${meta.alerted_at}.`,
                `4 hours later the opp is still in ${stage.label} with no RJ task completion.`,
                `Mike: call this seller OR reassign.`,
                `Original RJ task ID: ${meta.task_id || "(missing)"}`,
                `Opp ID: ${oppId}`,
              ].join("\n"),
              dueDate: escDue,
              assignedTo: USER_MIKE,
            }).catch(() => {});

            await env.DIAL_STATE.put(escKey, new Date().toISOString(), { expirationTtl: 60 * 60 * 24 * 30 });
            escalationsSent++;
          }
        } catch (e) {
          console.warn(`[hot-alerts] escalation check failed for ${oppId}: ${e}`);
        }
      }
    }
  }

  if (alertsSent || escalationsSent || tasksCreated) {
    console.log(`[hot-alerts] alerts=${alertsSent} tasks=${tasksCreated} escalations=${escalationsSent}`);
  }
}

// ============================================================================
// Phase 3.2 — Drip Agent
// ============================================================================
//
// Resurrects stale opps in Qualified / LAO / Follow-Up-1.5mo with a friendly,
// personalized nurture SMS generated by Claude Haiku. Mido confirmed "B" for
// scope (all three stages, not just Qualified).
//
// Architecture:
//   - Per-stage candidate pull (capped at 50 per stage)
//   - Per-opp 7-day cooldown (KV `drip:last_sent:<opp_id>`)
//   - 24h stage-age minimum (don't drip an opp the same day it landed)
//   - TCPA quiet-hours check (reuses inCallWindow; SMS is treated like a call)
//   - Skip DND, missing phone, opted-out tags
//   - Daily cap: 20 sends per run (configurable per request)
//   - Killswitch: KV `drip_agent:enabled` defaults to OFF (no auto-fire)
//
// Manual trigger: POST /admin/drip/run?limit=20&dry=true|false
// Killswitch:     POST /admin/drip/enable?value=true|false
// History:        GET  /admin/drip/recent?limit=50

const DRIP_TARGET_STAGES: Array<{ id: string; label: string; min_idle_hours: number }> = [
  { id: STAGE_QUALIFIED, label: "Qualified",         min_idle_hours: 24 },
  { id: STAGE_LAO,       label: "LAO (Prequalified)", min_idle_hours: 72 },
  { id: STAGE_FU_1_5MO,  label: "Follow-Up 1.5mo",   min_idle_hours: 24 },
];

// Tags that disqualify an opp from drip outreach (in addition to dnd flag).
const DRIP_BLOCKED_TAGS = new Set([
  "do-not-text", "dnd-opt-out", "wrong-number", "stop", "dnc",
  "opted-out", "complaint", "drip-blocked",
]);

interface DripCandidate {
  opp_id: string;
  contact_id: string;
  stage_id: string;
  stage_label: string;
  first_name: string;
  last_name: string;
  phone: string;
  address: string;
  state: string;
  tags: string[];
  has_replied_tag: boolean;
  updated_at: string;
  hours_since_updated: number;
}

async function gatherDripCandidates(env: Env): Promise<DripCandidate[]> {
  const out: DripCandidate[] = [];
  const nowMs = Date.now();

  for (const stage of DRIP_TARGET_STAGES) {
    const r = await fetch(
      `${GHL_BASE}/opportunities/search?` +
        new URLSearchParams({
          location_id: APG_LOCATION_ID,
          pipeline_id: ACQ_PIPELINE_ID,
          pipeline_stage_id: stage.id,
          limit: "50",
        }).toString(),
      { headers: ghlHeaders(env.BLAKE_GHL_PIT) }
    );
    if (!r.ok) {
      console.warn(`[drip] candidate search failed for ${stage.label}: ${r.status}`);
      continue;
    }
    const j: any = await r.json();
    const opps: any[] = j?.opportunities ?? [];

    for (const opp of opps) {
      const oppId = opp?.id;
      const contact = opp?.contact || {};
      const contactId = contact?.id;
      if (!oppId || !contactId) continue;

      const phone = String(contact.phone || "").trim();
      if (!phone || phone.length < 10) continue;
      if (contact.dnd === true) continue;

      const tags: string[] = (contact.tags || []).map((t: string) => String(t).toLowerCase());
      const blocked = tags.find((t) => DRIP_BLOCKED_TAGS.has(t));
      if (blocked) continue;

      const updatedAt = opp?.updatedAt || opp?.dateUpdated || "";
      const updatedMs = Date.parse(updatedAt) || 0;
      const hoursSince = updatedMs ? (nowMs - updatedMs) / (1000 * 60 * 60) : 9999;
      if (hoursSince < stage.min_idle_hours) continue;

      // Per-opp 7-day cooldown
      const lastSent = await env.DIAL_STATE.get(`drip:last_sent:${oppId}`);
      if (lastSent) {
        const lastMs = Date.parse(lastSent) || 0;
        const daysSince = (nowMs - lastMs) / (1000 * 60 * 60 * 24);
        if (daysSince < 7) continue;
      }

      // Parse address from opp name "Name - Address - Phone" (or legacy slashes)
      const oppName = (opp?.name || "").trim();
      const sep = oppName.includes(" - ") ? " - " : " / ";
      const parts = oppName.split(sep).map((s: string) => s.trim());
      const address = parts[1] || "";

      out.push({
        opp_id: oppId,
        contact_id: contactId,
        stage_id: stage.id,
        stage_label: stage.label,
        first_name: titleCaseName(String(contact.firstName || contact.first_name || "").trim()),
        last_name:  titleCaseName(String(contact.lastName  || contact.last_name  || "").trim()),
        phone,
        address,
        state: String(contact.state || "").trim().toUpperCase(),
        tags,
        has_replied_tag: tags.includes("customer replied"),
        updated_at: updatedAt,
        hours_since_updated: Math.round(hoursSince),
      });
    }
  }

  // Prioritize: replied-tag first (highest intent), then oldest idle first.
  out.sort((a, b) => {
    if (a.has_replied_tag !== b.has_replied_tag) return a.has_replied_tag ? -1 : 1;
    return b.hours_since_updated - a.hours_since_updated;
  });
  return out;
}

async function generateDripSmsForCandidate(
  env: Env,
  c: DripCandidate,
): Promise<{ ok: true; body: string } | { ok: false; error: string }> {
  if (!env.ANTHROPIC_API_KEY) return { ok: false, error: "no_anthropic_key" };

  const first = c.first_name || "there";
  const addrHint = c.address ? ` about ${c.address}` : "";
  const stageHint =
    c.stage_id === STAGE_QUALIFIED  ? "they had a conversation with our team but haven't booked yet" :
    c.stage_id === STAGE_LAO        ? "they got a prequalified offer from us but haven't responded" :
    c.stage_id === STAGE_FU_1_5MO   ? "we touched base ~6 weeks ago; circling back" :
    "previously engaged with us";

  const prompt = `You are Mike from Atom Property Group (APG), a NJ+PA cash home buyer. Write ONE short follow-up SMS to ${first}${addrHint}.

CONTEXT: ${stageHint}. ${c.has_replied_tag ? `They previously REPLIED to our SMS — high intent.` : `No prior SMS reply on file.`} Last touch: ${c.hours_since_updated}h ago.

CONSTRAINTS:
- Length: 1-2 sentences, max ~160 chars. ZERO emoji.
- Tone: warm, low-pressure, professional. Like a friendly text from a real person.
- DO NOT say "we noticed", "checking in", "just following up", "wanted to reach out" — these are tells.
- DO NOT mention "cash offer" in the first sentence — too aggressive for re-engagement.
- DO ask a SOFT question that invites a yes/no/short reply (e.g. "still considering selling?", "any update on ${c.address || "your situation"}?").
- DO NOT sign with a name (the SMS sender is configured server-side).
- Plain ASCII only.

Return ONLY the SMS text. No quotes, no preamble, no JSON.`;

  try {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-haiku-4-5-20251001",
        max_tokens: 200,
        messages: [{ role: "user", content: prompt }],
      }),
    });
    if (!res.ok) {
      const txt = await res.text();
      return { ok: false, error: `anthropic_${res.status}: ${txt.slice(0, 200)}` };
    }
    const data: any = await res.json();
    let text = "";
    for (const block of data.content || []) {
      if (block.type === "text") text += block.text;
    }
    const cleaned = text.trim().replace(/^["']|["']$/g, "").trim();
    if (!cleaned || cleaned.length > 240) {
      return { ok: false, error: `bad_length: ${cleaned.length}` };
    }
    return { ok: true, body: cleaned };
  } catch (e: any) {
    return { ok: false, error: `fetch_threw: ${e?.message || e}` };
  }
}

interface DripRunResult {
  ok: boolean;
  dry_run: boolean;
  enabled: boolean;
  candidates_total: number;
  candidates_considered: number;
  sent: number;
  skipped_quiet_hours: number;
  failed: number;
  cap: number;
  results: Array<{
    opp_id: string;
    stage: string;
    name: string;
    address: string;
    sent: boolean;
    skipped?: string;
    error?: string;
    body_preview?: string;
  }>;
}

async function runDripAgent(
  env: Env,
  opts: { limit: number; dryRun: boolean; ignoreKillswitch?: boolean },
): Promise<DripRunResult> {
  const enabled = (await env.DIAL_STATE.get("drip_agent:enabled")) === "true";
  if (!enabled && !opts.dryRun && !opts.ignoreKillswitch) {
    return {
      ok: false, dry_run: false, enabled: false,
      candidates_total: 0, candidates_considered: 0,
      sent: 0, skipped_quiet_hours: 0, failed: 0,
      cap: opts.limit, results: [],
    };
  }

  const candidates = await gatherDripCandidates(env);
  const considered = candidates.slice(0, opts.limit);
  const out: DripRunResult = {
    ok: true, dry_run: opts.dryRun, enabled,
    candidates_total: candidates.length,
    candidates_considered: considered.length,
    sent: 0, skipped_quiet_hours: 0, failed: 0,
    cap: opts.limit, results: [],
  };

  const now = new Date();
  for (const c of considered) {
    const displayName = `${c.first_name} ${c.last_name}`.trim() || "(unknown)";

    // TCPA: respect 8am-9pm local in the contact's state
    if (c.state && !inCallWindow(c.state, now)) {
      out.skipped_quiet_hours++;
      out.results.push({
        opp_id: c.opp_id, stage: c.stage_label, name: displayName,
        address: c.address, sent: false, skipped: "quiet_hours",
      });
      continue;
    }

    const gen = await generateDripSmsForCandidate(env, c);
    if (!gen.ok) {
      out.failed++;
      out.results.push({
        opp_id: c.opp_id, stage: c.stage_label, name: displayName,
        address: c.address, sent: false, error: gen.error,
      });
      continue;
    }

    if (opts.dryRun) {
      out.results.push({
        opp_id: c.opp_id, stage: c.stage_label, name: displayName,
        address: c.address, sent: false, skipped: "dry_run",
        body_preview: gen.body,
      });
      continue;
    }

    const sms = await sendGhlSms(env, c.contact_id, gen.body);
    if (sms.ok) {
      out.sent++;
      // 7-day per-opp cooldown
      await env.DIAL_STATE.put(
        `drip:last_sent:${c.opp_id}`,
        new Date().toISOString(),
        { expirationTtl: 60 * 60 * 24 * 7 },
      );
      // Sent log (30-day TTL) for /admin/drip/recent
      await env.DIAL_STATE.put(
        `drip:sent:${Date.now()}`,
        JSON.stringify({
          at: Date.now(),
          opp_id: c.opp_id,
          contact_id: c.contact_id,
          stage_id: c.stage_id,
          stage_label: c.stage_label,
          name: displayName,
          phone: c.phone,
          address: c.address,
          has_replied_tag: c.has_replied_tag,
          body: gen.body,
        }),
        { expirationTtl: 60 * 60 * 24 * 30 },
      );
      // Add a "drip-sent" tag so we can audit + filter in GHL
      await addTag(env.BLAKE_GHL_PIT, c.contact_id, "drip-sent").catch(() => {});
      out.results.push({
        opp_id: c.opp_id, stage: c.stage_label, name: displayName,
        address: c.address, sent: true, body_preview: gen.body,
      });
    } else {
      out.failed++;
      out.results.push({
        opp_id: c.opp_id, stage: c.stage_label, name: displayName,
        address: c.address, sent: false, error: `sms_${sms.status}: ${sms.body.slice(0, 80)}`,
      });
    }
  }

  if (out.sent > 0) {
    console.log(`[drip] sent=${out.sent} considered=${out.candidates_considered} of ${out.candidates_total}`);
  }
  return out;
}

// =============================================================================
// Multi-user admin route handler — dispatched from main fetch() above.
// Every route here requires a valid v2 session AND role >= manager (except /me
// which any signed-in user can hit).
// =============================================================================
async function handleAdminRoutes(req: Request, env: Env, url: URL): Promise<Response> {
  const auth = await requireAuthV2(req, env);
  if (!auth.ok || !auth.user) {
    return new Response(null, {
      status: 302,
      headers: { Location: `/login?next=${encodeURIComponent(url.pathname + url.search)}` },
    });
  }
  const me = auth.user;
  const topNav = apgTopNav("admin", me);

  // ---- /me — any signed-in user ----
  if (req.method === "GET" && url.pathname === "/me") {
    return new Response(adminPageHtml({
      title: "My Profile",
      topNav,
      body: renderMeBody(me),
    }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  }

  if (req.method === "POST" && url.pathname === "/me/rotate-password") {
    if (auth.legacy) {
      return new Response(adminPageHtml({
        title: "My Profile",
        topNav,
        body: renderMeBody(me),
        flash: { kind: "error", text: "Legacy session — sign in with your email + password first, then rotate." },
      }), { status: 400, headers: { "content-type": "text/html; charset=utf-8" } });
    }
    const fresh = await getUser(env, me.email);
    if (!fresh) return new Response("Not found", { status: 404 });
    const newPass = generatePassphrase();
    const salt = generateRandomSaltHex();
    fresh.password_hash = await hashPassword(newPass, salt, env.DASHBOARD_SESSION_SECRET);
    fresh.password_salt = salt;
    await putUser(env, fresh);
    await audit(env, { actor: me.email, action: "rotate_password", target: me.email });
    return new Response(adminPageHtml({
      title: "My Profile",
      topNav,
      body: renderMeBody(fresh),
      flash: { kind: "success", text: `New password generated: ${newPass}  —  save it now; it is not recoverable.` },
    }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  }

  // ---- /admin/* — manager+ only ----
  if (me.role === "employee") {
    return new Response(adminPageHtml({
      title: "Access denied",
      topNav,
      body: `<header class="adm-hero"><div><h1>Access <em>denied</em>.</h1><p>This area is restricted to managers. Contact Adam or Kebrina if you need broader access.</p></div><div class="btn-row"><a class="btn" href="/">Back to dashboard</a></div></header>`,
    }), { status: 403, headers: { "content-type": "text/html; charset=utf-8" } });
  }

  // ---- /admin/users — list view ----
  if (req.method === "GET" && (url.pathname === "/admin/users" || url.pathname === "/admin/users/")) {
    const [users, recent] = await Promise.all([listUsers(env), listRecentAudit(env, 25)]);
    return new Response(adminPageHtml({
      title: "Team",
      topNav,
      body: renderUsersListBody(users, me, recent),
    }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  }

  // ---- /admin/users/new ----
  if (req.method === "GET" && url.pathname === "/admin/users/new") {
    const templates = await listTemplates(env);
    return new Response(adminPageHtml({
      title: "Invite a teammate",
      topNav,
      body: renderUsersNewBody(me, templates),
    }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  }

  if (req.method === "POST" && url.pathname === "/admin/users/new") {
    const form = await req.formData();
    const name = String(form.get("name") || "").trim();
    const email = normalizeEmail(String(form.get("email") || ""));
    let role = String(form.get("role") || "employee").toLowerCase() as Role;
    const template = String(form.get("template") || "").trim();

    // Hard guardrails: managers cannot create CEO/Manager accounts.
    if (me.role === "manager" && role !== "employee") role = "employee";
    if (!["ceo", "manager", "employee"].includes(role)) role = "employee";
    if (!name || !email || !email.includes("@")) {
      const templates = await listTemplates(env);
      return new Response(adminPageHtml({
        title: "Invite a teammate",
        topNav,
        body: renderUsersNewBody(me, templates),
        flash: { kind: "error", text: "Name and a valid email are both required." },
      }), { status: 400, headers: { "content-type": "text/html; charset=utf-8" } });
    }
    const exists = await getUser(env, email);
    if (exists) {
      const templates = await listTemplates(env);
      return new Response(adminPageHtml({
        title: "Invite a teammate",
        topNav,
        body: renderUsersNewBody(me, templates),
        flash: { kind: "error", text: `A user with email ${email} already exists.` },
      }), { status: 409, headers: { "content-type": "text/html; charset=utf-8" } });
    }

    // Permissions: start from template if given, then layer per-checkbox.
    let perms = defaultPermsForRole(role);
    if (template && role === "employee") {
      const t = await getTemplate(env, template);
      if (t) perms = { ...t.permissions };
    }
    // For any role, if the form actually submitted perm:* checkboxes, those
    // take precedence over the template default.
    const formHadPerms = Array.from(form.keys()).some((k) => k.startsWith("perm:"));
    if (formHadPerms) perms = parsePermsFromForm(form, role);
    perms = clampPermsForRole(role, perms);

    const password = generatePassphrase();
    const salt = generateRandomSaltHex();
    const hash = await hashPassword(password, salt, env.DASHBOARD_SESSION_SECRET);
    const u: User = {
      email,
      name,
      role,
      template: template || undefined,
      permissions: perms,
      password_hash: hash,
      password_salt: salt,
      created_at: new Date().toISOString(),
      created_by: me.email,
    };
    await putUser(env, u);
    await audit(env, {
      actor: me.email,
      action: "create_user",
      target: email,
      details: { role, template: template || null },
    });
    const templates = await listTemplates(env);
    return new Response(adminPageHtml({
      title: "Invite a teammate",
      topNav,
      body: renderUsersNewBody(me, templates, { kind: "success", text: `User ${name} (${email}) created.`, newPassword: password, newEmail: email }),
    }), { status: 201, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  }

  // ---- /admin/users/<email>/delete (GET for the confirm-link UX) ----
  if (req.method === "GET" && url.pathname.startsWith("/admin/users/") && url.pathname.endsWith("/delete")) {
    const targetEmail = normalizeEmail(decodeURIComponent(url.pathname.slice("/admin/users/".length, -"/delete".length)));
    const target = await getUser(env, targetEmail);
    if (!target) return new Response("Not found", { status: 404 });
    // Permission: CEO can remove anyone except themselves; manager can only
    // remove employees they (or another manager) created.
    if (target.email === me.email) return new Response("Cannot remove yourself.", { status: 400 });
    if (me.role === "manager" && target.role !== "employee") {
      return new Response("Managers can only remove employees.", { status: 403 });
    }
    await deleteUser(env, target.email);
    await audit(env, {
      actor: me.email,
      action: "delete_user",
      target: target.email,
      details: { role: target.role, name: target.name },
    });
    return new Response(null, { status: 302, headers: { Location: "/admin/users" } });
  }

  // ---- /admin/users/<email> — edit (GET) + save (POST) ----
  if (url.pathname.startsWith("/admin/users/") && !url.pathname.endsWith("/delete") && url.pathname !== "/admin/users/new") {
    const targetEmail = normalizeEmail(decodeURIComponent(url.pathname.slice("/admin/users/".length)));
    const target = await getUser(env, targetEmail);
    if (!target) return new Response("Not found", { status: 404 });
    // Permission: managers can only edit employees.
    if (me.role === "manager" && target.role !== "employee" && target.email !== me.email) {
      return new Response("Managers can only edit employees.", { status: 403 });
    }
    const templates = await listTemplates(env);

    if (req.method === "GET") {
      return new Response(adminPageHtml({
        title: `Edit ${target.name}`,
        topNav,
        body: renderUserEditBody(me, target, templates),
      }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }

    if (req.method === "POST") {
      const form = await req.formData();
      const action = String(form.get("action") || "save");
      const name = String(form.get("name") || target.name).trim();
      let role = String(form.get("role") || target.role).toLowerCase() as Role;
      const template = String(form.get("template") || "").trim();
      if (me.role === "manager") role = "employee"; // can't promote
      if (!["ceo", "manager", "employee"].includes(role)) role = target.role;

      if (action === "regen_password") {
        const newPass = generatePassphrase();
        const salt = generateRandomSaltHex();
        target.password_hash = await hashPassword(newPass, salt, env.DASHBOARD_SESSION_SECRET);
        target.password_salt = salt;
        await putUser(env, target);
        await audit(env, { actor: me.email, action: "regen_password", target: target.email });
        return new Response(adminPageHtml({
          title: `Edit ${target.name}`,
          topNav,
          body: renderUserEditBody(me, target, templates, { kind: "success", text: "New password generated below.", newPassword: newPass }),
        }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
      }

      // Save changes — clamp perms by final role, audit the change.
      const formHadPerms = Array.from(form.keys()).some((k) => k.startsWith("perm:"));
      let perms: Permissions = target.permissions;
      if (template && template !== target.template) {
        const t = await getTemplate(env, template);
        if (t) perms = { ...t.permissions };
      }
      if (formHadPerms) perms = parsePermsFromForm(form, role);
      perms = clampPermsForRole(role, perms);

      const before = { role: target.role, template: target.template, permissions: target.permissions };
      target.name = name;
      target.role = role;
      target.template = template || undefined;
      target.permissions = perms;
      await putUser(env, target);
      await audit(env, {
        actor: me.email,
        action: "update_user",
        target: target.email,
        details: { before, after: { role, template: target.template, permissions: perms } },
      });
      return new Response(adminPageHtml({
        title: `Edit ${target.name}`,
        topNav,
        body: renderUserEditBody(me, target, templates, { kind: "success", text: "Changes saved." }),
      }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
    }
  }

  // ---- /admin/templates — read-only list (edit UI deferred) ----
  if (req.method === "GET" && url.pathname === "/admin/templates") {
    const templates = await listTemplates(env);
    return new Response(adminPageHtml({
      title: "Templates",
      topNav,
      body: renderTemplatesBody(templates),
    }), { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  }

  return new Response("Not found", { status: 404 });
}

// Helper for admin routes — random 16-byte salt as hex.
function generateRandomSaltHex(): string {
  const b = new Uint8Array(16);
  crypto.getRandomValues(b);
  let s = "";
  for (let i = 0; i < b.length; i++) s += b[i].toString(16).padStart(2, "0");
  return s;
}

